window.QSBI_LESSONS=window.QSBI_LESSONS||{};QSBI_LESSONS[10]=[{"id":"10_19","g":10,"l":19,"topic":"Инфляция: что это и как измеряют","module":"Финансовая грамотность","format":"Комбинированный","skills":["Финансовое мышление","Критическое мышление","Принятие решений"],"goal":"К концу урока ученик сможет объяснить причины инфляции и по данным индекса потребительских цен (ИПЦ) рассчитать, на сколько процентов подорожала корзина товаров.","criteria":["Я объясняю, что такое инфляция и ИПЦ, и называю причины инфляции.","Я правильно рассчитываю процент подорожания корзины.","Я делаю вывод, как инфляция влияет на людей и бизнес."],"result":"Расчёт «Моя корзина»: стоимость условной корзины в двух периодах, процент подорожания, сравнение с ИПЦ и объяснение возможных причин.","stages":[{"stage":"Разминка «Найди пару»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Инфляция (inflation)","real":"Устойчивый рост общего уровня цен","shown":"Устойчивый рост общего уровня цен","truth":true,"first":"И"},{"term":"Потребительская корзина","real":"Набор товаров и услуг, по которому оценивают изменение цен","shown":"Снижение общего уровня цен","truth":false,"first":"П"},{"term":"ИПЦ","real":"Индекс потребительских цен, показывает, во сколько раз изменилась стоимость корзины","shown":"Индекс потребительских цен, показывает, во сколько раз изменилась стоимость корзины","truth":true,"first":"И"},{"term":"Инфляция спроса","real":"Рост цен, когда спрос растёт быстрее, чем предложение","shown":"Набор товаров и услуг, по которому оценивают изменение цен","truth":false,"first":"И"},{"term":"Инфляция издержек","real":"Рост цен из-за подорожания сырья, топлива, доставки","shown":"Рост цен из-за подорожания сырья, топлива, доставки","truth":true,"first":"И"},{"term":"Дефляция","real":"Снижение общего уровня цен","shown":"Рост цен, когда спрос растёт быстрее, чем предложение","truth":false,"first":"Д"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Инфляция (inflation)","def":"Устойчивый рост общего уровня цен"},{"term":"Потребительская корзина","def":"Набор товаров и услуг, по которому оценивают изменение цен"},{"term":"ИПЦ","def":"Индекс потребительских цен, показывает, во сколько раз изменилась стоимость корзины"},{"term":"Инфляция спроса","def":"Рост цен, когда спрос растёт быстрее, чем предложение"},{"term":"Инфляция издержек","def":"Рост цен из-за подорожания сырья, топлива, доставки"},{"term":"Дефляция","def":"Снижение общего уровня цен"},{"term":"Базовый период","def":"Период, с которым сравнивают цены"}],"english":"inflation — инфляция; money — деньги","concepts":{"head":"Определения","items":["Инфляция (inflation) — рост цен, из-за которого деньги (money) теряют покупательную способность.","ИПЦ показывает, сколько стоит фиксированная корзина товаров и услуг сейчас по сравнению с базовым периодом."]},"steps":{"head":"Как это работает","items":["Причины: инфляция спроса (у людей больше денег, а товаров столько же), инфляция издержек (подорожали сырьё, топливо, перевозки), ослабление национальной валюты (дороже импорт), ожидания (продавцы заранее повышают цены). Как считать:","Стоимость корзины в базовом периоде = Σ цена × количество","То же в текущем периоде","ИПЦ = текущая ÷ базовая × 100","Инфляция = ИПЦ − 100 (%)"]},"scheme":"«весы цен»: слева корзина базового года, справа текущего; под ними формула ИПЦ; сбоку четыре стрелки причин: спрос, издержки, курс, ожидания.","examples":[{"lab":"Казахстанский","text":"Условная корзина"},{"lab":"Школьника из Кокшетау","text":"10 буханок хлеба по 200 тенге, 5 л молока по 450, 20 поездок на автобусе по 150, 1 тетрадь-набор 1 500. Было: 2 000 + 2 250 + 3 000 + 1 500 = 8 750. Через год: хлеб 216, молоко 486, проезд 150, набор 1 650: 2 160 + 2 430 + 3 000 + 1 650 = 9 240. ИПЦ = 9 240 ÷ 8 750 × 100 ≈ 105,6; инфляция ≈ 5,6%."},{"lab":"Второй пример","text":"Если выросла только цена топлива, дорожает доставка и затем — товары в магазинах: это инфляция издержек."}],"mistake":{"myth":"Складывать проценты подорожания отдельных товаров","fix":"Вклад товара зависит от его доли в корзине."},"check":[{"q":"Почему считают корзину, а не один товар?","a":"Один товар может дорожать по своей причине"},{"q":"Если ИПЦ = 108, какова инфляция?","a":"8%"},{"q":"Почему проезд мог не подорожать?","a":"Тарифы регулируются"}],"kz":{"text":"Бюро национальной статистики РК ежемесячно рассчитывает индекс потребительских цен и публикует его на сайте stat.gov.kz, а Национальный банк РК использует эти данные при принятии решений о базовой ставке.","link":"ученики видят, что ИПЦ — реальный официальный показатель."},"world":{"text":"Глобальная волна инфляции 2021–2023 годов затронула многие страны: подорожали энергоносители, продовольствие и доставка из-за сбоев в цепочках поставок. Стабильность цен связана с ЦУР ООН 2 «Ликвидация голода» и ЦУР 8.","link":""},"fact":"Одну из первых попыток измерить общий рост цен с помощью индекса связывают с английским епископом Уильямом Флитвудом, который в 1707 году сравнивал цены на зерно, мясо, напитки и ткань за несколько столетий.","cards":[{"n":"1","title":"Корзина «Студент»","lines":["Товар — количество — цена в базовом году — цена сейчас:","Рис, кг — 4 — 500 — 560","Яйца, десяток — 2 — 900 — 990","Молоко, л — 6 — 450 — 495","Проезд, поездка — 30 — 150 — 150","Мобильная связь, мес. — 1 — 3 000 — 3 300","Задание: 1) Посчитайте стоимость корзины в двух периодах. 2) Найдите ИПЦ и инфляцию. 3) Для каждого товара предложите причину подорожания."],"hand":"Сдать: таблицу и вывод.","answers":[["Тренеру","Базовый 2 000 + 1 800 + 2 700 + 4 500 + 3 000 = 14 000; сейчас 2 240 + 1 980 + 2 970 + 4 500 + 3 300 = 14 990; ИПЦ ≈ 107,1; инфляция ≈ 7,1%."]]},{"n":"2","title":"Олимпиадная задача","lines":["Корзина стоила 50 000 тенге. Первый год цены выросли на 5%, второй — на 8%. Сколько стоит корзина? На сколько процентов выросли цены за 2 года?"],"hand":"Сдать: решение.","answers":[["","50 000 × 1,05 × 1,08 = 56 700 тенге; рост 13,4% (а не 13%"]]}],"homework":"Составь свою условную корзину из 5 товаров с ценами «тогда» и «сейчас» (можно спросить родственников о ценах прошлого года), посчитай ИПЦ и инфляцию корзины.","support":"Таблица с готовыми столбцами «цена × количество»; образец расчёта первой строки.","advanced":"Олимпиадная задача из Карточки 2 и вопрос: как изменится результат, если в корзине вдвое больше хлеба?","photo":{"src":"lessons/img/10_19.jpg","author":"Jack Lee","q":["Что вы видите на фото? Как это связано с нашей темой?","Почему события в одной части мира влияют на цены в нашем магазине?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g10-l19.pptx","name":"19. Инфляция — что это и как измеряют (10 кл).pptx","mb":1.6}},{"id":"10_20","g":10,"l":20,"topic":"Финансовая цель и подушка безопасности: практикум","module":"Финансовая грамотность","format":"Проектная мастерская","skills":["Финансовое мышление","Принятие решений","Командная работа"],"goal":"К концу урока ученик сможет рассчитать подушку безопасности на 3–6 месяцев обязательных расходов и составить помесячный план накопления к финансовой цели с учётом инфляции.","criteria":["Я правильно рассчитываю подушку безопасности на 3–6 месяцев обязательных расходов.","Я составляю реалистичный план накопления к цели с учётом инфляции.","Я обосновываю, где хранить подушку и почему."],"result":"План «Подушка + цель» для условного героя: расчёт подушки на 3 и 6 месяцев, ежемесячная сумма накоплений, график по месяцам и выбор места хранения.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":4},{"stage":"Постановка задачи","min":4},{"stage":"Работа в командах","min":20},{"stage":"Промежуточный показ","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Финансы (finance)","real":"Управление деньгами: доходами, расходами, сбережениями","shown":"Управление деньгами: доходами, расходами, сбережениями","truth":true,"first":"Ф"},{"term":"Цель (goal)","real":"Конкретная сумма к конкретному сроку","shown":"Конкретная, измеримая, достижимая, значимая и ограниченная по сроку цель","truth":false,"first":"Ц"},{"term":"Практика (practice)","real":"Применение знаний на задаче","shown":"Применение знаний на задаче","truth":true,"first":"П"},{"term":"Подушка безопасности","real":"Запас денег на 3–6 месяцев обязательных расходов на случай потери дохода или непредвиденных трат","shown":"Конкретная сумма к конкретному сроку","truth":false,"first":"П"},{"term":"Ликвидность","real":"Насколько быстро можно получить деньги без потерь","shown":"Насколько быстро можно получить деньги без потерь","truth":true,"first":"Л"},{"term":"SMART-цель","real":"Конкретная, измеримая, достижимая, значимая и ограниченная по сроку цель","shown":"Запас денег на 3–6 месяцев обязательных расходов на случай потери дохода или непредвиденных трат","truth":false,"first":"S"}],"perm":[3,2,1,0,5,4]},"glossary":[{"term":"Финансы (finance)","def":"Управление деньгами: доходами, расходами, сбережениями"},{"term":"Цель (goal)","def":"Конкретная сумма к конкретному сроку"},{"term":"Практика (practice)","def":"Применение знаний на задаче"},{"term":"Подушка безопасности","def":"Запас денег на 3–6 месяцев обязательных расходов на случай потери дохода или непредвиденных трат"},{"term":"Ликвидность","def":"Насколько быстро можно получить деньги без потерь"},{"term":"SMART-цель","def":"Конкретная, измеримая, достижимая, значимая и ограниченная по сроку цель"},{"term":"Норма сбережений","def":"Доля дохода, которую человек откладывает"}],"english":"finance — финансы; goal — цель; money — деньги; practice — практика","concepts":{"head":"Определения","items":["Подушка безопасности — запас денег (money), который защищает от потери дохода, болезни, поломки.","Финансовая цель (goal) — то, на что копят.","Сначала подушка, потом цель."]},"steps":{"head":"Как это работает, по шагам","items":["Посчитать обязательные расходы в месяц","Подушка = обязательные расходы × 3 (минимум) или × 6 (надёжно)","Сформулировать SMART-цель и учесть инфляцию: цена через год = цена × (1 + инфляция)","Ежемесячная сумма = (подушка + цель − уже накоплено) ÷ число месяцев","Проверить, реальна ли сумма для бюджета (норма сбережений)","Выбрать место хранения: подушка — ликвидно (накопительный счёт или вклад с возможностью снятия, под гарантией КФГД), цель — можно на срочный вклад"]},"scheme":"«два кармана»: левый «подушка — не трогать, ликвидно», правый «цель — к сроку»; над ними стрелка «доход − расходы = сбережения».","examples":[{"lab":"Казахстанский","text":"Условная молодая специалистка из Туркестана: доход на руки 280 000 условных тенге, обязательные расходы 170 000. Подушка на 3 месяца — 510 000, на 6 — 1 020 000. Цель — курсы за 300 000 через год, инфляция 7%: 321 000. Если копить 18 месяцев на подушку (3 месяца) и цель: (510 000 + 321 000) ÷ 18 ≈ 46 200 в месяц — 16,5% дохода, реально."},{"lab":"Второй пример","text":"При доходе 180 000 и обязательных 160 000 копить 46 000 невозможно — нужно сначала сократить расходы или растянуть срок."}],"mistake":{"myth":"Тратить подушку на «желания»","fix":"Разбираем правило: подушка — только для непредвиденного."},"check":[{"q":"Почему подушку считают от обязательных, а не всех расходов?","a":"В трудный период необязательное отключают"},{"q":"Где хранить подушку?","a":"Там, откуда можно быстро снять, под гарантией"},{"q":"Что делать, если сумма нереальна?","a":"Менять срок, цель или расходы"}],"kz":{"text":"Казахстанский фонд гарантирования депозитов защищает сберегательные вклады в тенге до 20 млн тенге на вкладчика в одном банке-участнике, и именно это делает банковский вклад надёжным местом хранения подушки.","link":"выбор места хранения — часть плана."},"world":{"text":"По данным обзора Всемирного банка Global Findex, значительная часть взрослых в мире не может быстро найти деньги на срочный крупный расход. Финансовая устойчивость домохозяйств связана с ЦУР ООН 1 «Ликвидация нищеты».","link":""},"fact":"Правило «плати сначала себе» (pay yourself first) популяризировала книга Джорджа Клейсона «Самый богатый человек в Вавилоне» 1926 года: откладывать часть каждого дохода до того, как тратить. Книга до сих пор издаётся по всему миру.","cards":[{"n":"1","title":"Герои","lines":["Герой А: Айдос, 22 года, доход на руки 250 000 условных тенге, обязательные расходы 150 000, накоплено 50 000.","Цель: ноутбук для работы 400 000 через 12 месяцев.","Герой Б: Жанар, 25 лет, доход 320 000, обязательные 210 000, накоплений нет.","Цель: курсы английского 240 000 через 9 месяцев.","Герой В: Ерлан, 19 лет, доход 150 000, обязательные 110 000, накоплено 20 000.","Цель: подушка на 6 месяцев.","Инфляция для целей: 7% в год (для срока меньше года берите 7% полностью для упрощения).","Задание: подушка на 3 и 6 месяцев, цена цели с инфляцией, ежемесячная сумма, доля от дохода, место хранения."],"hand":"Сдать: план в таблице.","answers":[]},{"n":"2","title":"Критерии и олимпиадная задача","lines":["Критерии: верная подушка (3 балла), учтена инфляция (2), реалистичная ежемесячная сумма (3), обосновано место хранения (2).","Олимпиадная задача: обязательные расходы 120 000 тенге в месяц. Подушка на 4 месяца копится по 40 000 в месяц. Через сколько месяцев она будет готова?"],"hand":"Сдать: лист взаимооценки и решение.","answers":[["","120 000 × 4 = 480 000; 480 000 ÷ 40 000 = 12 месяцев."]]}],"homework":"Сформулируй свою SMART-цель на год (сумма, срок) и посчитай, сколько нужно откладывать в месяц с учётом инфляции 7%. Без указания доходов семьи.","support":"Шаблон с формулами-подсказками; герой А с простыми числами; пример расчёта из конспекта.","advanced":"Олимпиадная задача из Карточки 2 и сценарий: доход героя пропал на 2 месяца — на сколько отодвинется цель?","photo":{"src":"lessons/img/10_20.jpg","author":"Towfiqu barbhuiya","q":["Что вы видите на фото? Как это связано с нашей темой?","Как подушка безопасности помогает человеку пережить кризис без долгов?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g10-l20.pptx","name":"20. Финансовая цель и подушка безопасности — практикум (10 кл).pptx","mb":1.4}},{"id":"10_21","g":10,"l":21,"topic":"Банки и банковские продукты","module":"Финансовая грамотность","format":"Комбинированный","skills":["Финансовое мышление","Критическое мышление","Принятие решений"],"goal":"К концу урока ученик сможет объяснить, как работают платёжная карта, депозит и кредит, и выбрать подходящий банковский продукт для заданной жизненной ситуации с обоснованием.","criteria":["Я объясняю, как банк зарабатывает и как работают карта, депозит и кредит.","Я выбираю продукт для каждой ситуации и обосновываю выбор.","Я называю риск каждого продукта и как его снизить."],"result":"Таблица «Ситуация — продукт — почему» для 5 жизненных ситуаций с кратким обоснованием и одним риском для каждого выбора.","stages":[{"stage":"Разминка «Угадай слово»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Банк (bank)","real":"Коммерческая финансовая организация, которая принимает деньги, выдаёт кредиты и проводит платежи ради прибыли","shown":"Коммерческая финансовая организация, которая принимает деньги, выдаёт кредиты и проводит платежи ради прибыли","truth":true,"first":"Б"},{"term":"Некоммерческая организация (non-profit)","real":"Организация, цель которой не прибыль, а общественная польза","shown":"Деньги банка в долг с возвратом и вознаграждением","truth":false,"first":"Н"},{"term":"Дебетовая карта","real":"Карта для оплаты своими деньгами","shown":"Карта для оплаты своими деньгами","truth":true,"first":"Д"},{"term":"Кредитная карта","real":"Карта с лимитом денег банка, которые нужно вернуть","shown":"Организация, цель которой не прибыль, а общественная польза","truth":false,"first":"К"},{"term":"Депозит","real":"Деньги в банке под вознаграждение","shown":"Деньги в банке под вознаграждение","truth":true,"first":"Д"},{"term":"Кредит","real":"Деньги банка в долг с возвратом и вознаграждением","shown":"Карта с лимитом денег банка, которые нужно вернуть","truth":false,"first":"К"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Банк (bank)","def":"Коммерческая финансовая организация, которая принимает деньги, выдаёт кредиты и проводит платежи ради прибыли"},{"term":"Некоммерческая организация (non-profit)","def":"Организация, цель которой не прибыль, а общественная польза"},{"term":"Дебетовая карта","def":"Карта для оплаты своими деньгами"},{"term":"Кредитная карта","def":"Карта с лимитом денег банка, которые нужно вернуть"},{"term":"Депозит","def":"Деньги в банке под вознаграждение"},{"term":"Кредит","def":"Деньги банка в долг с возвратом и вознаграждением"},{"term":"Процентная маржа","def":"Разница между ставками по кредитам и депозитам, основной источник дохода банка"}],"english":"bank — банк; non-profit — некоммерческая организация; money — деньги","concepts":{"head":"Определения","items":["Банк (bank) — коммерческая организация: он привлекает деньги (money) вкладчиков под меньший процент и выдаёт кредиты под больший; разница — процентная маржа — его доход, плюс комиссии.","Некоммерческая организация (non-profit), например благотворительный фонд или ассоциация, не распределяет прибыль, а тратит средства на свою миссию."]},"steps":{"head":"Как работают продукты, по шагам","items":["Карта: деньги на счёте → оплата → списание; дебетовая — свои деньги, кредитная — деньги банка в пределах лимита, часто с льготным периодом","Депозит: клиент кладёт деньги → банк начисляет вознаграждение → защита КФГД (сберегательные вклады в тенге до 20 млн тенге)","Кредит: банк выдаёт сумму → клиент возвращает её частями с вознаграждением; главное — ГЭСВ и долговая нагрузка","Алгоритм выбора: цель → срок → нужен ли доступ к деньгам → риск"]},"scheme":"«банк посередине»: слева вкладчики с стрелкой «депозит, банк платит r₁», справа заёмщики со стрелкой «кредит, клиент платит r₂», внизу «r₂ − r₁ = доход банка».","examples":[{"lab":"Казахстанский","text":"Студентка из Алматы получает стипендию на дебетовую карту и оплачивает проезд — ей нужна карта без платы за обслуживание."},{"lab":"Второй пример","text":"Условный предприниматель из Актау хочет купить кофемашину за 900 000 условных тенге для кофейни: выручка позволит платить 85 000 в месяц, — здесь уместен кредит на оборудование, если окупаемость выше переплаты."}],"mistake":{"myth":"Считать кредитную карту «своими деньгами»","fix":"Льготный период закончится, и придётся платить вознаграждение."},"check":[{"q":"Откуда у банка деньги на кредиты?","a":"Из депозитов и других источников"},{"q":"Чем дебетовая карта отличается от кредитной?","a":"Свои деньги против денег банка"},{"q":"Чем некоммерческая организация отличается от банка?","a":"Не ставит целью прибыль"}],"kz":{"text":"Halyk Bank (Народный банк Казахстана) — один из крупнейших и старейших банков страны, а Kaspi.kz — пример цифровой финансовой платформы.","link":"у разных банков разные модели, но продукты — карта, депозит, кредит — одинаковые по сути."},"world":{"text":"Мобильный сервис M-Pesa в Кении, запущенный в 2007 году, позволил миллионам людей без банковского счёта переводить деньги с телефона. Это пример ЦУР ООН 8.10 — расширения доступа к финансовым услугам.","link":""},"fact":"Одним из старейших действующих банков мира считается итальянский банк Monte dei Paschi di Siena, основанный в 1472 году. Он работает более 550 лет.","cards":[{"n":"1","title":"Пять ситуаций","lines":["1) Дана, 17 лет, получает деньги за подработку и платит за проезд.","2) Семья копит на ремонт через 2 года, деньги не понадобятся раньше.","3) Молодой мастер хочет купить инструменты за 400 000 условных тенге, они окупятся за 8 месяцев.","4) Студент хочет новый телефон «прямо сейчас», денег нет, дохода стабильного нет.","5) Нужен запас на непредвиденные расходы, который можно снять в любой день.","Задание: для каждой ситуации укажите продукт, почему и один риск."],"hand":"Сдать: таблицу.","answers":[["Тренеру","1 — дебетовая карта; 2 — срочный депозит; 3 — кредит при расчёте окупаемости; 4 — лучше копить, кредит опасен; 5 — накопительный счёт или вклад с правом снятия."]]},{"n":"2","title":"Олимпиадная задача","lines":["Банк привлёк депозиты 10 млн тенге под условные 10% годовых и выдал их кредитами под условные 18%. Какой валовой процентный доход банка за год?"],"hand":"Сдать: решение.","answers":[["","10 млн × 18% − 10 млн × 10% = 1,8 млн − 1 млн = 800 000 тенге."]]}],"homework":"Найди на финансовом портале finreg.kz или на сайте любого банка описание одного продукта и выпиши 5 условий, которые важно проверить. Объясни, для какой ситуации он подходит.","support":"Подсказка «цель → продукт»: платить — карта, копить — депозит, купить сейчас — кредит; таблица с примером первой строки.","advanced":"Олимпиадная задача из Карточки 2 и вопрос: почему банк может предложить по вкладу ставку выше, если клиент не снимает деньги весь срок?","photo":{"src":"lessons/img/10_21.jpg","author":"Stephen Phillips","q":["Что вы видите на фото? Как это связано с нашей темой?","Как цифровые банки меняют жизнь людей в отдалённых районах?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g10-l21.pptx","name":"21. Банки и банковские продукты (10 кл).pptx","mb":1.4}},{"id":"10_22","g":10,"l":22,"topic":"Кредит: проценты и переплата","module":"Финансовая грамотность","format":"Комбинированный","skills":["Финансовое мышление","Критическое мышление","Принятие решений"],"goal":"К концу урока ученик сможет рассчитать переплату по кредиту и сравнить 2 предложения банков по полной стоимости (сумма всех платежей, комиссии, ГЭСВ) и выбрать выгодное.","criteria":["Я рассчитываю полную стоимость кредита и переплату с учётом всех комиссий.","Я сравниваю 2 предложения и объясняю, почему «низкий процент» не всегда выгоднее.","Я оцениваю долговую нагрузку и делаю ответственный вывод."],"result":"Сравнение двух кредитных предложений: таблица полной стоимости, переплата в тенге и процентах, вывод с учётом долговой нагрузки.","stages":[{"stage":"Разминка «Найди пару»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Кредит (loan)","real":"Деньги в долг, которые возвращают с вознаграждением","shown":"Деньги в долг, которые возвращают с вознаграждением","truth":true,"first":"К"},{"term":"Процент (percent), ставка вознаграждения","real":"Плата за пользование кредитом за год","shown":"Сумма всех платежей заёмщика","truth":false,"first":"П"},{"term":"Номинальная ставка","real":"Ставка, указанная в рекламе, без учёта комиссий","shown":"Ставка, указанная в рекламе, без учёта комиссий","truth":true,"first":"Н"},{"term":"ГЭСВ","real":"Годовая эффективная ставка вознаграждения: реальная стоимость кредита с учётом всех платежей","shown":"Плата за пользование кредитом за год","truth":false,"first":"Г"},{"term":"Комиссия за выдачу или обслуживание","real":"Дополнительная плата банку","shown":"Дополнительная плата банку","truth":true,"first":"К"},{"term":"Полная стоимость кредита","real":"Сумма всех платежей заёмщика","shown":"Годовая эффективная ставка вознаграждения: реальная стоимость кредита с учётом всех платежей","truth":false,"first":"П"}],"perm":[1,0,5,4,3,2]},"glossary":[{"term":"Кредит (loan)","def":"Деньги в долг, которые возвращают с вознаграждением"},{"term":"Процент (percent), ставка вознаграждения","def":"Плата за пользование кредитом за год"},{"term":"Номинальная ставка","def":"Ставка, указанная в рекламе, без учёта комиссий"},{"term":"ГЭСВ","def":"Годовая эффективная ставка вознаграждения: реальная стоимость кредита с учётом всех платежей"},{"term":"Комиссия за выдачу или обслуживание","def":"Дополнительная плата банку"},{"term":"Полная стоимость кредита","def":"Сумма всех платежей заёмщика"},{"term":"Переплата","def":"Полная стоимость минус сумма кредита"}],"english":"percent — процент; loan — кредит; money — деньги","concepts":{"head":"Определения","items":["Кредит (loan) стоит денег (money): кроме возврата основного долга заёмщик платит вознаграждение — процент (percent) — и иногда комиссии.","Номинальная ставка — «витрина», а ГЭСВ показывает реальную цену.","По закону банки обязаны указывать ГЭСВ в договоре и рекламе."]},"steps":{"head":"Как сравнивать, по шагам","items":["Выписать сумму, срок, ежемесячный платёж, комиссии","Полная стоимость = платёж × число месяцев + все комиссии","Переплата = полная стоимость − сумма кредита","Переплата в % от суммы","Сравнить ГЭСВ, если она указана","Долговая нагрузка = платёж ÷ доход","Выбрать предложение с меньшей полной стоимостью и посильной нагрузкой"]},"scheme":"Два «чека» рядом: «Банк А» и «Банк Б» со строками «платежи», «комиссии», «итого», «переплата»; стрелка «сравниваем ИТОГО, а не платёж».","examples":[{"lab":"Казахстанский","text":"Условный кредит 600 000 тенге на 12 месяцев для мастерской в Талдыкоргане. Банк А: платёж 55 000, комиссий нет: полная стоимость 660 000, переплата 60 000 (10%). Банк Б: «низкая ставка», платёж 53 000, но комиссия за выдачу 30 000 и страховка 12 000: 636 000 + 42 000 = 678 000, переплата 78 000 (13%). Выгоднее А, хотя платёж больше."},{"lab":"Второй пример","text":"Тот же кредит на 24 месяца с платежом 30 000: полная стоимость 720 000, переплата 120 000 — платёж меньше, но переплата вдвое больше."}],"mistake":{"myth":"Сравнивать кредиты по рекламной ставке или по платежу","fix":"Разбираем пример с банком Б."},"check":[{"q":"Почему маленький ежемесячный платёж может означать большую переплату?","a":"Длинный срок"},{"q":"Что показывает ГЭСВ?","a":"Реальную стоимость кредита"},{"q":"Что ещё проверить, кроме переплаты?","a":"Долговую нагрузку"}],"kz":{"text":"В Казахстане банки обязаны указывать ГЭСВ, а АРРФР контролирует соблюдение прав заёмщиков и публикует на финансовом портале finreg.kz материалы о кредитах.","link":"ГЭСВ — главный инструмент сравнения."},"world":{"text":"Во многих странах закон обязывает кредиторов раскрывать полную стоимость кредита: в США — Truth in Lending Act 1968 года, в ЕС — директива о потребительском кредите. Это защищает потребителей и связано с ЦУР ООН 16.","link":""},"fact":"Закон США Truth in Lending Act 1968 года впервые массово обязал кредиторов показывать годовую ставку (APR), чтобы люди могли сравнивать кредиты. Это стало образцом для многих стран.","cards":[{"n":"1","title":"Два предложения","lines":["Герой 1: Мадина хочет купить швейную машину для мини-ателье за 450 000 условных тенге. Доход на руки 220 000.","Банк «Север»: 12 платежей по 41 500, комиссия за выдачу 9 000.","Банк «Юг»: 12 платежей по 42 000, комиссий нет.","Герой 2: Арман хочет кредит 1 000 000 на ремонт. Доход 300 000.","Банк «Восток»: 24 платежа по 50 000, без комиссий.","Банк «Запад»: 36 платежей по 36 000, страховка 20 000.","Задание: полная стоимость, переплата (тенге и %), нагрузка, выбор."],"hand":"Сдать: таблицу.","answers":[["Тренеру","«Север» 498 000 + 9 000 = 507 000, переплата 57 000 (12,7%); «Юг» 504 000, переплата 54 000 (12%), нагрузка ≈ 19% — выгоднее «Юг». «Восток» 1 200 000, переплата 200 000, нагрузка ≈ 16,7%; «Запад» 1 296 000 + 20 000 = 1 316 000, переплата 316 000, нагрузка 12%."]]},{"n":"2","title":"Олимпиадная задача","lines":["Кредит 200 000 тенге. Вариант 1: 10 платежей по 22 000. Вариант 2: 12 платежей по 18 500 и комиссия 3 000. Какой вариант дешевле и на сколько?","Ответ: 1 — 220 000 (переплата 20 000); 2 — 222 000 + 3 000 = 225 000 (переплата 25 000). Вариант 1 дешевле на 5 000 тенге."],"hand":"Сдать: решение.","answers":[]}],"homework":"Рассчитай переплату для условного кредита 500 000 тенге в трёх вариантах: 12 платежей по 46 000, 24 платежа по 25 500, 36 платежей по 18 000. Сделай вывод о связи срока и переплаты.","support":"Шаблон «чека» с пустыми строками; подсказка «итого = платёж × месяцы + комиссии».","advanced":"Олимпиадная задача из Карточки 2 и вопрос: какой доход нужен, чтобы платёж 55 000 тенге не превышал трети дохода?","photo":{"src":"lessons/img/10_22.jpg","author":"Towfiqu barbhuiya","q":["Что вы видите на фото? Как это связано с нашей темой?","Почему государство обязывает банки показывать реальную стоимость кредита?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g10-l22.pptx","name":"22. Кредит — проценты и переплата (10 кл).pptx","mb":1.4}},{"id":"10_23","g":10,"l":23,"topic":"Ярмарка: личный бюджет продавца","module":"Финансовая грамотность","format":"Симуляция, ярмарка","skills":["Финансовое мышление","Работа с клиентом","Принятие решений"],"goal":"К концу урока ученик сможет вести на ярмарке учёт своих доходов и расходов как продавца и рассчитать выручку, затраты, прибыль и личный финансовый результат.","criteria":["Я записываю каждую продажу и расход без пропусков.","Я правильно считаю выручку, затраты и прибыль.","Я объясняю, как решения во время ярмарки повлияли на мой результат."],"result":"Журнал учёта продавца: план продаж, запись каждой операции во время ярмарки и итоговый расчёт прибыли и личного бюджета продавца.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":4},{"stage":"Подготовка","min":6},{"stage":"Ярмарка","min":18},{"stage":"Подсчёт","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Ярмарка (fair)","real":"Учебная торговая площадка с условными тенге","shown":"Учебная торговая площадка с условными тенге","truth":true,"first":"Я"},{"term":"Продавец (seller)","real":"Участник, который предлагает товар и ведёт учёт продаж","shown":"Выручка минус затраты","truth":false,"first":"П"},{"term":"Бюджет (budget) продавца","real":"План вложений, продаж и расходов","shown":"План вложений, продаж и расходов","truth":true,"first":"Б"},{"term":"Выручка","real":"Все деньги от продаж","shown":"Участник, который предлагает товар и ведёт учёт продаж","truth":false,"first":"В"},{"term":"Себестоимость","real":"Затраты на изготовление одной единицы товара","shown":"Затраты на изготовление одной единицы товара","truth":true,"first":"С"},{"term":"Прибыль","real":"Выручка минус затраты","shown":"Все деньги от продаж","truth":false,"first":"П"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Ярмарка (fair)","def":"Учебная торговая площадка с условными тенге"},{"term":"Продавец (seller)","def":"Участник, который предлагает товар и ведёт учёт продаж"},{"term":"Бюджет (budget) продавца","def":"План вложений, продаж и расходов"},{"term":"Выручка","def":"Все деньги от продаж"},{"term":"Себестоимость","def":"Затраты на изготовление одной единицы товара"},{"term":"Прибыль","def":"Выручка минус затраты"},{"term":"Точка безубыточности","def":"Количество продаж, при котором выручка равна затратам"}],"english":"fair — ярмарка; seller — продавец; budget — бюджет; money — деньги","concepts":{"head":"Определения","items":["Продавец (seller) на ярмарке (fair) — маленький предприниматель.","Его бюджет (budget) — план: сколько вложить, по какой цене продавать и сколько продать.","Деньги (money) — условные тенге-купоны."]},"steps":{"head":"Как это работает, по шагам","items":["Себестоимость единицы = все затраты ÷ количество изделий","Цена выше себестоимости","Точка безубыточности = затраты ÷ цена (округляем вверх)","Во время ярмарки записываем каждую операцию: время, товар, количество, сумма","После — выручка, прибыль, сравнение с планом"]},"scheme":"График «прямая затрат и прямая выручки», точка их пересечения — безубыточность; рядом журнал учёта «Время — Товар — Кол-во — Сумма».","examples":[{"lab":"Казахстанский","text":"Продавец из Атырау сделал 20 брелоков, затраты 4 000 условных тенге, себестоимость 200. Цена 500. Точка безубыточности 4 000 ÷ 500 = 8 штук. Продал 14: выручка 7 000, прибыль 3 000."},{"lab":"Второй пример","text":"Продавец снизил цену до 400 после события рынка и продал все 20: выручка 8 000, прибыль 4 000 — снижение цены дало больше прибыли."}],"mistake":{"myth":"Продавец считает выручку прибылью","fix":"Из 7 000 выручки 4 000 — возврат затрат."},"check":[{"q":"Что такое точка безубыточности?","a":"Продажи, при которых нет ни прибыли, ни убытка"},{"q":"Почему важно записывать сразу?","a":"Иначе потеряются операции"},{"q":"Может ли снижение цены увеличить прибыль?","a":"Да, если сильно растут продажи"}],"kz":{"text":"Зелёный базар в Алматы — один из самых известных рынков Казахстана, где тысячи продавцов ежедневно ведут свой маленький бизнес: закупают товар, ставят цену и считают выручку.","link":"каждый продавец там решает те же задачи, что и участник школьной ярмарки."},"world":{"text":"Международная организация Fairtrade сертифицирует товары, за которые производители получают справедливую цену, а покупатели видят прозрачную цепочку. Это связано с ЦУР ООН 12 «Ответственное потребление и производство».","link":""},"fact":"Термин «точка безубыточности» (break-even point) широко используется в экономике с начала XX века; анализ безубыточности остаётся одним из первых расчётов, которые делают предприниматели при запуске бизнеса.","cards":[{"n":"1","title":"План продавца","lines":["Стартовые затраты на материалы ___ тенге; количество изделий ___; себестоимость = затраты ÷ количество ___; цена ___; точка безубыточности = затраты ÷ цена ___ шт.; план продаж ___ шт.; план выручки ___; план прибыли ___.","Журнал: Время | Товар | Кол-во | Сумма | Покупатель доволен?","Итог: выручка, затраты, прибыль, отклонение от плана."],"hand":"Сдать: заполненную карточку.","answers":[["","Да/нет"]]},{"n":"2","title":"События рынка","lines":["1) «Наплыв покупателей: 3 минуты все покупают по 2 штуки».","2) «Конкурент снизил цену на 20%: решите за 1 минуту, отвечаете ли вы».","3) «Налоговая проверка учёта: тренер проверяет журнал; если записи не сходятся — штраф 300 тенге»."],"hand":"Сдать: решение в журнале.","answers":[]}],"homework":"Перенеси журнал учёта в таблицу, посчитай прибыль и точку безубыточности, напиши 3 предложения о том, что изменишь в цене или ассортименте в следующий раз.","support":"Журнал с готовыми столбцами и примером первой записи; калькулятор у каждого продавца.","advanced":"Рассчитать, какую цену нужно было поставить, чтобы получить прибыль 5 000 при фактическом количестве продаж.","photo":{"src":"lessons/img/10_23.jpg","author":"Nguyễn Đức","q":["Что вы видите на фото? Как это связано с нашей темой?","Какие правила честной торговли мы можем ввести на нашей ярмарке?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g10-l23.pptx","name":"23. Ярмарка — личный бюджет продавца (10 кл).pptx","mb":1.7}},{"id":"10_24","g":10,"l":24,"topic":"Налоги: зачем нужны и какие бывают","module":"Финансовая грамотность","format":"Комбинированный","skills":["Финансовое мышление","Критическое мышление","Принятие решений"],"goal":"К концу урока ученик сможет различить прямые и косвенные налоги на примерах Казахстана и объяснить, какие общественные блага финансируются за счёт налогов.","criteria":["Я объясняю, что такое налог и зачем он нужен.","Я различаю прямые и косвенные налоги и привожу примеры.","Я связываю налоги с общественными благами, которые получают люди."],"result":"Карта налогов: классификация 6 налогов на прямые и косвенные, кто платит и куда идут деньги, плюс схема «налог → бюджет → общественное благо».","stages":[{"stage":"Разминка «Угадай слово»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Налог (tax)","real":"Обязательный безвозмездный платёж в государственный бюджет","shown":"Обязательный безвозмездный платёж в государственный бюджет","truth":true,"first":"Н"},{"term":"Прямой налог","real":"Налог, который платят непосредственно с дохода или имущества: ИПН, корпоративный подоходный налог, налог на имущество, налог на транспорт","shown":"То, чем пользуются все: дороги, освещение, безопасность","truth":false,"first":"П"},{"term":"Косвенный налог","real":"Налог, включённый в цену товара: НДС, акцизы; платит покупатель, перечисляет продавец","shown":"Налог, включённый в цену товара: НДС, акцизы; платит покупатель, перечисляет продавец","truth":true,"first":"К"},{"term":"НДС","real":"Налог на добавленную стоимость, в Казахстане 16%","shown":"Налог, который платят непосредственно с дохода или имущества: ИПН, корпоративный подоходный налог, налог на имущество, налог на транспорт","truth":false,"first":"Н"},{"term":"ИПН","real":"Индивидуальный подоходный налог, 10% (15% с годового дохода свыше 8 500 МРП)","shown":"Индивидуальный подоходный налог, 10% (15% с годового дохода свыше 8 500 МРП)","truth":true,"first":"И"},{"term":"Общественное благо","real":"То, чем пользуются все: дороги, освещение, безопасность","shown":"Налог на добавленную стоимость, в Казахстане 16%","truth":false,"first":"О"}],"perm":[3,2,1,0,5,4]},"glossary":[{"term":"Налог (tax)","def":"Обязательный безвозмездный платёж в государственный бюджет"},{"term":"Прямой налог","def":"Налог, который платят непосредственно с дохода или имущества: ИПН, корпоративный подоходный налог, налог на имущество, налог на транспорт"},{"term":"Косвенный налог","def":"Налог, включённый в цену товара: НДС, акцизы; платит покупатель, перечисляет продавец"},{"term":"НДС","def":"Налог на добавленную стоимость, в Казахстане 16%"},{"term":"ИПН","def":"Индивидуальный подоходный налог, 10% (15% с годового дохода свыше 8 500 МРП)"},{"term":"Общественное благо","def":"То, чем пользуются все: дороги, освещение, безопасность"},{"term":"Государственный бюджет","def":"План доходов и расходов государства"}],"english":"tax — налог; money — деньги","concepts":{"head":"Определения","items":["Налог (tax) — обязательный платёж, на который государство финансирует то, что нужно всем.","Деньги (money) налогоплательщиков идут в бюджет, а оттуда — на школы, больницы, дороги, безопасность, пособия."]},"steps":{"head":"Как это работает, по шагам","items":["Человек или компания получает доход или покупает товар","С дохода платится прямой налог (например, ИПН 10%, а с годового дохода свыше 8 500 МРП — 15%; МРП 2026 года — 4 325 тенге)","В цене товара уже есть косвенный налог — НДС 16%; продавец собирает его и перечисляет в бюджет","Бюджет распределяет деньги на общественные блага. Для ИП на упрощённой декларации — 4% от дохода"]},"scheme":"Два входящих потока в «бюджет»: «прямые — с дохода и имущества» и «косвенные — в цене товаров»; выходящие стрелки: «образование», «здравоохранение», «дороги», «безопасность», «социальная поддержка».","examples":[{"lab":"Казахстанский","text":"Покупатель из Шымкента купил наушники за 11 600 условных тенге. В цене — НДС 16%: 11 600 × 16 ÷ 116 = 1 600 тенге; он заплатил косвенный налог, даже не заметив этого."},{"lab":"Второй пример","text":"Условная учительница получает начисленные 300 000; её ИПН (с учётом ОПВ и вычета 30 МРП) — 14 025 тенге, это прямой налог."}],"mistake":{"myth":"«Я не работаю, значит налоги не плачу»","fix":"Каждый покупатель платит НДС."},"check":[{"q":"НДС — прямой или косвенный?","a":"Косвенный"},{"q":"Кто реально платит НДС?","a":"Покупатель, в цене товара"},{"q":"Почему уличное освещение — общественное благо?","a":"Пользуются все, нельзя исключить никого"}],"kz":{"text":"В Казахстане с 2026 года действует новый Налоговый кодекс, и на сайте Комитета государственных доходов kgd.gov.kz публикуются актуальные ставки и разъяснения.","link":"ученики видят, что ставки НДС 16% и ИПН 10% — официальные."},"world":{"text":"Скандинавские страны известны высокими налогами и одновременно высоким качеством общественных услуг — бесплатного образования и медицины. Налоговые системы связаны с ЦУР ООН 17.1 — мобилизация внутренних ресурсов для развития.","link":""},"fact":"Бенджамин Франклин в 1789 году написал знаменитую фразу: «В этом мире нет ничего определённого, кроме смерти и налогов». Её до сих пор цитируют в разговорах о налогах.","cards":[{"n":"1","title":"Карта налогов","lines":["Налоги: ИПН; НДС; акциз на бензин; налог на имущество физических лиц; налог на транспортные средства; налог ИП на упрощённой декларации (4% от дохода).","Задание: для каждого укажите: прямой или косвенный; кто платит; с чего берётся; пример блага, которое финансирует бюджет."],"hand":"Сдать: таблицу.","answers":[]},{"n":"2","title":"Олимпиадная задача","lines":["Цена куртки с НДС — 23 200 условных тенге. 1) Сколько в цене НДС (16%)? 2) Какой была бы цена без НДС?","Дополнительно: ИП на упрощёнке получил за месяц доход 500 000 тенге. Сколько налога по ставке 4%?"],"hand":"Сдать: решение.","answers":[["","23 200 × 16 ÷ 116 = 3 200 тенге; без НДС 20 000 тенге."],["","20 000 тенге."]]}],"homework":"Возьми 3 любых чека (без личных данных), найди в них НДС или вычисли его (цена × 16 ÷ 116). Назови 3 общественных блага в своём районе, которые финансируются из бюджета.","support":"Таблица с двумя колонками «прямой / косвенный» и подсказками «с дохода? в цене?»; калькулятор.","advanced":"Олимпиадная задача из Карточки 2 и вопрос: почему косвенные налоги легче собирать, но они сильнее ощущаются людьми с небольшим доходом?","photo":{"src":"lessons/img/10_24.jpg","author":"Kelly Sikkema","q":["Что вы видите на фото? Как это связано с нашей темой?","Какой баланс между налогами и общественными благами кажется вам справедливым?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g10-l24.pptx","name":"24. Налоги — зачем нужны и какие бывают (10 кл).pptx","mb":1.4}},{"id":"10_25","g":10,"l":25,"topic":"Налоги в чеке и в зарплате: практикум","module":"Финансовая грамотность","format":"Проектная мастерская","skills":["Финансовое мышление","Командная работа","Критическое мышление"],"goal":"К концу урока ученик сможет найти и вычислить НДС 16% в чеке и рассчитать ИПН и ОПВ с условной зарплаты, получив сумму на руки.","criteria":["Я правильно выделяю НДС из цены с НДС (× 16 ÷ 116).","Я правильно рассчитываю ОПВ, ИПН с вычетом 30 МРП и сумму на руки.","Я объясняю расчёты команде и проверяю чужие расчёты."],"result":"Командный «налоговый практикум»: разобранные 3 чека с выделенным НДС и расчётные листы 3 работников с ОПВ, ИПН и суммой на руки.","stages":[{"stage":"Разминка «Найди пару»","min":4},{"stage":"Постановка задачи","min":4},{"stage":"Работа в командах","min":20},{"stage":"Промежуточный показ","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Налог (tax)","real":"Обязательный платёж в бюджет","shown":"Обязательный платёж в бюджет","truth":true,"first":"Н"},{"term":"Зарплата (salary)","real":"Оплата труда по договору","shown":"Обязательные пенсионные взносы работника, 10%","truth":false,"first":"З"},{"term":"Практика (practice)","real":"Применение правил на реальных задачах","shown":"Применение правил на реальных задачах","truth":true,"first":"П"},{"term":"НДС","real":"Налог на добавленную стоимость, 16%, входит в цену товара","shown":"Оплата труда по договору","truth":false,"first":"Н"},{"term":"Цена с НДС","real":"Сумма, которую платит покупатель; НДС в ней = цена × 16 ÷ 116","shown":"Сумма, которую платит покупатель; НДС в ней = цена × 16 ÷ 116","truth":true,"first":"Ц"},{"term":"ОПВ","real":"Обязательные пенсионные взносы работника, 10%","shown":"Налог на добавленную стоимость, 16%, входит в цену товара","truth":false,"first":"О"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Налог (tax)","def":"Обязательный платёж в бюджет"},{"term":"Зарплата (salary)","def":"Оплата труда по договору"},{"term":"Практика (practice)","def":"Применение правил на реальных задачах"},{"term":"НДС","def":"Налог на добавленную стоимость, 16%, входит в цену товара"},{"term":"Цена с НДС","def":"Сумма, которую платит покупатель; НДС в ней = цена × 16 ÷ 116"},{"term":"ОПВ","def":"Обязательные пенсионные взносы работника, 10%"},{"term":"ИПН","def":"Индивидуальный подоходный налог, 10% с дохода после ОПВ и базового вычета 30 МРП (129 750 тенге)"}],"english":"tax — налог; salary — зарплата; money — деньги; practice — практика","concepts":{"head":"Определения","items":["Налог (tax) — платёж в бюджет.","Косвенный налог — НДС 16% — сидит внутри цены товара.","Прямые удержания из зарплаты (salary): ОПВ 10% на пенсионный счёт и ИПН 10%.","Деньги (money) на руки — то, что остаётся."]},"steps":{"head":"Как считать, по шагам","items":["НДС в чеке:","Найти сумму с НДС","НДС = сумма × 16 ÷ 116","Цена без НДС = сумма − НДС. Зарплата:","ОПВ = начислено × 10%","Облагаемый доход = начислено − ОПВ − 129 750 (30 МРП × 4 325)","ИПН = облагаемый × 10% (если меньше нуля — 0)","На руки = начислено − ОПВ − ИПН. Работодатель сверху платит ОПВР 3,5%"]},"scheme":"Слева «чек»: «итого 5 800 → внутри НДС 800»; справа «зарплата»: лестница 350 000 → −ОПВ 35 000 → −вычет → ИПН 18 525 → на руки 296 475.","examples":[{"lab":"Казахстанский","text":"Чек супермаркета в Астане на 5 800 условных тенге: НДС = 5 800 × 16 ÷ 116 = 800; без НДС 5 000."},{"lab":"Второй пример","text":"Монтажник, начислено 350 000: ОПВ 35 000; облагаемый 350 000 − 35 000 − 129 750 = 185 250; ИПН 18 525; на руки 296 475 тенге; ОПВР работодателя 12 250."}],"mistake":{"myth":"Считать НДС как 16% от цены с НДС (5 800 × 16% = 928)","fix":"928 — неверно, правильно 800."},"check":[{"q":"Почему НДС делят на 116, а не на 100?","a":"Цена уже включает 16%"},{"q":"Уменьшает ли ОПВ налоговую базу ИПН?","a":"Да"},{"q":"Кто платит ОПВР?","a":"Работодатель"}],"kz":{"text":"Казахстанская система eGov.kz и кабинет налогоплательщика на kgd.gov.kz позволяют проверять налоговые платежи и пенсионные взносы онлайн, а с 2026 года действует новый Налоговый кодекс со ставкой НДС 16%.","link":"работник может сам проверить, правильно ли с него удержаны ИПН и ОПВ."},"world":{"text":"Эстония известна тем, что большинство граждан подают налоговую декларацию онлайн за несколько минут; цифровое налоговое администрирование связано с ЦУР ООН 16.6 — эффективные и прозрачные институты.","link":""},"fact":"Налог на добавленную стоимость впервые ввела Франция в 1954 году; его разработчиком считают Мориса Лоре. Сегодня НДС действует в большинстве стран мира.","cards":[{"n":"1","title":"Три чека","lines":["Чек 1: продукты — 11 600 условных тенге. Чек 2: кроссовки — 34 800. Чек 3: канцтовары — 2 320.","Для каждого: НДС = сумма × 16 ÷ 116; цена без НДС.","Ответы для тренера: 1 600 и 10 000; 4 800 и 30 000; 320 и 2 000."],"hand":"Сдать: таблицу.","answers":[]},{"n":"2","title":"Три работника","lines":["Вычет 129 750; ОПВ 10%; ИПН 10%; ОПВР 3,5% (работодатель).","А: официант, начислено 170 000. Б: дизайнер, начислено 420 000. В: стажёр, начислено 130 000.","Найдите ОПВ, облагаемый доход, ИПН, на руки, ОПВР.","Ответы для тренера: А — 17 000; 23 250; 2 325; 150 675; 5 950. Б — 42 000; 248 250; 24 825; 353 175; 14 700. В — 13 000; облагаемый < 0; ИПН 0; 117 000; 4 550.","Олимпиадная задача: в чеке указано «итого 9 280 тенге, в т.ч. НДС». Продавец утверждает, что НДС 1 484,8. Прав ли он?"],"hand":"Сдать: расчётные листы и решение.","answers":[["","Нет, 1 484,8 — это 16% от 9 280; правильно 9 280 × 16 ÷ 116 = 1 280 тенге."]]}],"homework":"Рассчитай зарплату на руки для начисленных 160 000, 280 000 и 500 000 тенге. Найди НДС в 2 своих чеках (без личных данных).","support":"Шаблон с формулами по шагам; готовое значение вычета 129 750; образец расчёта первого чека.","advanced":"Олимпиадная задача из Карточки 2 и вопрос: сколько всего стоит работодателю работник с начислением 350 000 тенге с учётом ОПВР?","photo":{"src":"lessons/img/10_25.jpg","author":"Kelly Sikkema","q":["Что вы видите на фото? Как это связано с нашей темой?","Как цифровые сервисы делают уплату налогов проще и честнее?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g10-l25.pptx","name":"25. Налоги в чеке и в зарплате — практикум (10 кл).pptx","mb":1.6}},{"id":"10_26","g":10,"l":26,"topic":"Трудовой договор и первая зарплата","module":"Финансовая грамотность","format":"Комбинированный","skills":["Финансовое мышление","Критическое мышление","Принятие решений"],"goal":"К концу урока ученик сможет назвать 5 обязательных пунктов трудового договора и права работника до 18 лет и рассчитать первую зарплату на руки по условиям договора.","criteria":["Я называю 5 обязательных пунктов трудового договора.","Я объясняю права работника до 18 лет и нахожу их нарушения.","Я рассчитываю первую зарплату на руки по условиям договора."],"result":"Проверенный трудовой договор подростка: чек-лист обязательных пунктов, найденные нарушения прав несовершеннолетнего и расчёт первой зарплаты на руки.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Трудовой договор (contract)","real":"Письменное соглашение работника и работодателя об условиях работы и оплаты","shown":"Письменное соглашение работника и работодателя об условиях работы и оплаты","truth":true,"first":"Т"},{"term":"Зарплата (salary)","real":"Оплата труда, указанная в договоре","shown":"Документ, где видно начисление, удержания и сумму на руки","truth":false,"first":"З"},{"term":"Трудовая функция","real":"Работа по должности, которую выполняет работник","shown":"Работа по должности, которую выполняет работник","truth":true,"first":"Т"},{"term":"Сокращённое рабочее время","real":"Норма для работников до 18 лет: не более 24 часов в неделю в 14–16 лет и не более 36 часов в 16–18 лет","shown":"Оплата труда, указанная в договоре","truth":false,"first":"С"},{"term":"Налоговый агент","real":"Работодатель, который удерживает ИПН и ОПВ и перечисляет их","shown":"Работодатель, который удерживает ИПН и ОПВ и перечисляет их","truth":true,"first":"Н"},{"term":"Расчётный лист","real":"Документ, где видно начисление, удержания и сумму на руки","shown":"Норма для работников до 18 лет: не более 24 часов в неделю в 14–16 лет и не более 36 часов в 16–18 лет","truth":false,"first":"Р"}],"perm":[1,0,5,4,3,2]},"glossary":[{"term":"Трудовой договор (contract)","def":"Письменное соглашение работника и работодателя об условиях работы и оплаты"},{"term":"Зарплата (salary)","def":"Оплата труда, указанная в договоре"},{"term":"Трудовая функция","def":"Работа по должности, которую выполняет работник"},{"term":"Сокращённое рабочее время","def":"Норма для работников до 18 лет: не более 24 часов в неделю в 14–16 лет и не более 36 часов в 16–18 лет"},{"term":"Налоговый агент","def":"Работодатель, который удерживает ИПН и ОПВ и перечисляет их"},{"term":"Расчётный лист","def":"Документ, где видно начисление, удержания и сумму на руки"}],"english":"salary — зарплата; contract — договор; money — деньги","concepts":{"head":"Определения","items":["Трудовой договор (contract) — главный документ работника.","Зарплата (salary) в договоре — начисленная; на руки работник получает деньги (money) после удержания ОПВ 10% и ИПН 10%."]},"steps":{"head":"Как это работает, по шагам","items":["Проверить возраст: по Трудовому кодексу РК договор заключают с 16 лет; с 15 — при получении образования с письменного согласия родителя; с 14 — на лёгкую работу в свободное от учёбы время с согласия родителя","Проверить 5 обязательных пунктов: стороны договора; трудовая функция (должность); место работы; срок и дата начала; режим рабочего времени и размер оплаты","Проверить права до 18 лет: сокращённое время (24 часа в неделю для 14–16 лет, 36 — для 16–18), запрет ночных, сверхурочных, тяжёлых и вредных работ, обязательный медосмотр","Рассчитать первую зарплату: ОПВ = 10%; облагаемый = начислено − ОПВ − 129 750 (30 МРП); ИПН = 10%; на руки = начислено − ОПВ − ИПН. Если работал не весь месяц — начисление пропорционально отработанным часам"]},"scheme":"«договор-щит»: 5 обязательных пунктов по кругу, внутри «права до 18 лет»; справа «лестница зарплаты».","examples":[{"lab":"Казахстанский","text":"17-летний Тимур из Караганды работает помощником в IT-компании 30 часов в неделю, ставка 1 200 условных тенге в час. За 4 недели начислено 144 000; ОПВ 14 400; облагаемый 144 000 − 14 400 − 129 750 < 0, ИПН 0; на руки 129 600."},{"lab":"Второй пример","text":"15-летней предлагают 32 часа в неделю — нарушение нормы 24 часа."}],"mistake":{"myth":"Путать начисленную зарплату и сумму на руки при проверке договора","fix":"Разбираем пример Тимура."},"check":[{"q":"Сколько часов может работать 16-летний?","a":"До 36 в неделю"},{"q":"Можно ли подростку сверхурочные?","a":"Нет"},{"q":"Почему ИПН у Тимура 0?","a":"Доход после ОПВ меньше вычета"}],"kz":{"text":"Электронная биржа труда Enbek.kz позволяет искать вакансии и заключать электронные трудовые договоры, а нормы о работе несовершеннолетних закреплены в Трудовом кодексе РК (adilet.zan.kz).","link":"подросток может проверить условия вакансии до собеседования."},"world":{"text":"Международная организация труда приняла Конвенцию № 138 о минимальном возрасте и № 182 о наихудших формах детского труда; Казахстан их ратифицировал. Это связано с ЦУР ООН 8.7 и 8.8 — защита трудовых прав.","link":""},"fact":"Международная организация труда, созданная в 1919 году, — одно из старейших учреждений, сегодня входящих в систему ООН; в 1969 году она получила Нобелевскую премию мира.","cards":[{"n":"1","title":"Проверь договор","lines":["«ТОО „Быстрая доставка“ принимает Алию (16 лет) курьером. Режим: 6 дней по 8 часов, иногда ночные доставки. Оплата: 200 000 тенге в месяц. Испытательный срок по решению работодателя. Медосмотр не требуется. Место работы — по указанию менеджера. Дата начала — не указана».","Задание: найдите не менее 5 нарушений или пропусков; предложите исправления."],"hand":"Сдать: таблицу.","answers":[["Тренеру","48 часов при норме 36; ночная работа запрещена; нет медосмотра; не указаны место работы и дата начала; нет трудовой функции подробно."]]},{"n":"2","title":"Первая зарплата","lines":["Алия после исправления договора работает 36 часов в неделю по 1 400 условных тенге в час, 4 недели.","1) Начислено? (201 600.) 2) ОПВ? (20 160.) 3) Облагаемый доход? (51 690.) 4) ИПН? (5 169.) 5) На руки?","Олимпиадная задача: подросток 15 лет работает максимально разрешённое время 4 недели по 1 000 тенге в час. Сколько получит на руки?"],"hand":"Сдать: решения.","answers":[["1","176 271."],["","24 × 4 × 1 000 = 96 000; ОПВ 9 600; ИПН 0; на руки 86 400 тенге."]]},{"n":"3","title":"Роли собеседования","lines":["«Менеджер»: торопится, говорит «договор потом».","«Кандидат»: вежливо просит договор до начала работы и задаёт 3 вопроса."],"hand":"Сдать: не нужно.","answers":[]}],"homework":"Составь «идеальный договор» для летней подработки 16-летнего (5 обязательных пунктов, соблюдение прав до 18 лет) и рассчитай зарплату на руки за месяц при 30 часах в неделю и ставке 1 300 условных тенге в час.","support":"Чек-лист обязательных пунктов и прав до 18 лет; шаблон расчёта зарплаты с готовым вычетом.","advanced":"Олимпиадная задача из Карточки 2 и вопрос: при какой начисленной зарплате ИПН становится больше нуля? (Когда начислено × 0,9 > 129 750, то есть больше 144 167 тенге.)","photo":{"src":"lessons/img/10_26.jpg","author":"Scott Graham","q":["Что вы видите на фото? Как это связано с нашей темой?","Почему для подростков устанавливают особые правила труда?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g10-l26.pptx","name":"26. Трудовой договор и первая зарплата (10 кл).pptx","mb":1.4}},{"id":"10_27","g":10,"l":27,"topic":"После ярмарки: мой доход и налоги","module":"Финансовая грамотность","format":"Симуляция, ярмарка","skills":["Финансовое мышление","Принятие решений","Критическое мышление"],"goal":"К концу урока ученик сможет рассчитать свой доход за ярмарку и налог, который заплатил бы ИП на упрощённой декларации (4% от дохода), и сделать вывод о финансовом результате после налога.","criteria":["Я правильно считаю доход, затраты и прибыль по своему журналу ярмарки.","Я рассчитываю налог ИП на упрощённой декларации 4% от дохода.","Я объясняю, как налог влияет на результат и цену, и опираюсь на цифры."],"result":"Итоговый отчёт продавца: доход (выручка), затраты, прибыль до налога, налог ИП 4% от дохода, прибыль после налога и вывод.","stages":[{"stage":"Разминка «Угадай слово»","min":4},{"stage":"Подготовка","min":6},{"stage":"Ярмарка","min":18},{"stage":"Подсчёт","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Ярмарка (fair)","real":"Учебная торговая площадка с условными тенге","shown":"Учебная торговая площадка с условными тенге","truth":true,"first":"Я"},{"term":"Доход (income) ИП на упрощённой декларации","real":"Вся выручка от продаж за период","shown":"Доход минус затраты","truth":false,"first":"Д"},{"term":"Налог (tax) ИП на упрощёнке","real":"4% от дохода","shown":"4% от дохода","truth":true,"first":"Н"},{"term":"ИП","real":"Индивидуальный предприниматель, который ведёт бизнес от своего имени","shown":"Вся выручка от продаж за период","truth":false,"first":"И"},{"term":"Упрощённая декларация","real":"Специальный налоговый режим для малого бизнеса с простой формой отчётности","shown":"Специальный налоговый режим для малого бизнеса с простой формой отчётности","truth":true,"first":"У"},{"term":"Прибыль до налога","real":"Доход минус затраты","shown":"Индивидуальный предприниматель, который ведёт бизнес от своего имени","truth":false,"first":"П"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Ярмарка (fair)","def":"Учебная торговая площадка с условными тенге"},{"term":"Доход (income) ИП на упрощённой декларации","def":"Вся выручка от продаж за период"},{"term":"Налог (tax) ИП на упрощёнке","def":"4% от дохода"},{"term":"ИП","def":"Индивидуальный предприниматель, который ведёт бизнес от своего имени"},{"term":"Упрощённая декларация","def":"Специальный налоговый режим для малого бизнеса с простой формой отчётности"},{"term":"Прибыль до налога","def":"Доход минус затраты"},{"term":"Прибыль после налога","def":"Прибыль до налога минус налог"}],"english":"fair — ярмарка; income — доход; tax — налог; money — деньги","concepts":{"head":"Определения","items":["Доход (income) ИП на упрощённой декларации — это выручка, а не прибыль: налог (tax) 4% берётся со всей суммы продаж.","Деньги (money) ярмарки (fair) условные, но расчёт как у настоящего ИП."]},"steps":{"head":"Как считать, по шагам","items":["Из журнала ярмарки — выручка","Затраты на товар","Прибыль до налога = выручка − затраты","Налог = выручка × 4%","Прибыль после налога = прибыль до налога − налог","Доля налога в прибыли = налог ÷ прибыль до налога × 100%","Вывод — нужно ли учитывать налог в цене"]},"scheme":"«лестница»: выручка 10 000 → минус затраты 3 500 → прибыль 6 500 → минус налог 400 (4% от выручки!) → 6 100; стрелка от налога ведёт к «выручке», а не к прибыли.","examples":[{"lab":"Казахстанский","text":"Условный продавец из Семея на ярмарке продал 25 открыток по 400 тенге: выручка 10 000; затраты 3 500; прибыль до налога 6 500; налог 4% × 10 000 = 400; прибыль после налога 6 100. Налог — около 6% прибыли."},{"lab":"Второй пример","text":"Продавец с маленькой наценкой: выручка 10 000, затраты 9 000, прибыль 1 000, налог 400 — это уже 40% прибыли. Вывод: при упрощёнке налог от выручки сильнее бьёт по бизнесу с низкой наценкой."}],"mistake":{"myth":"Считать 4% от прибыли","fix":"4% × 6 500 = 260 — неверно, правильно 400."},"check":[{"q":"С чего считается налог ИП на упрощёнке?","a":"С дохода — выручки"},{"q":"Почему продавцу с низкой наценкой налог ощутимее?","a":"Налог от выручки съедает большую долю маленькой прибыли"},{"q":"Куда идут налоги?","a":"В бюджет на общественные блага"}],"kz":{"text":"В Казахстане многие начинающие предприниматели работают как ИП на упрощённой декларации; сдать декларацию и проверить платежи можно через кабинет налогоплательщика на kgd.gov.kz и портал eGov.kz.","link":"ученик считает налог так же, как настоящий ИП."},"world":{"text":"Во многих странах для малого бизнеса есть упрощённые налоговые режимы с налогом от оборота, чтобы начинающим было проще вести учёт; это поддерживает ЦУР ООН 8.3 — развитие малых предприятий.","link":""},"fact":"Одним из первых известных налоговых документов считают глиняные таблички Шумера, где записывались сборы с урожая и скота ещё около 4–5 тысяч лет назад. Так налоги и учёт появились одновременно с письменностью.","cards":[{"n":"1","title":"Отчёт продавца","lines":["Выручка (доход) ___; затраты ___; прибыль до налога = выручка − затраты ___; налог ИП = выручка × 4% ___; прибыль после налога ___; доля налога в прибыли ___%.","Вывод (2 предложения): ___."],"hand":"Сдать: заполненную карточку.","answers":[]},{"n":"2","title":"Налоговое событие и олимпиадная задача","lines":["Событие: «Налоговый инспектор ярмарки: каждый продавец сдаёт 4% выручки повторного дня в „бюджет класса“ сразу».","Олимпиадная задача: ИП продал товаров на 250 000 тенге, затраты 180 000. Найдите налог по упрощёнке и прибыль после налога."],"hand":"Сдать: решение.","answers":[["","Налог 250 000 × 4% = 10 000; прибыль 70 000 − 10 000 = 60 000 тенге."]]}],"homework":"Оформи отчёт продавца: выручка, затраты, прибыль, налог 4%, прибыль после налога. Рассчитай, на сколько нужно было поднять цену, чтобы налог не уменьшил прибыль.","support":"Шаблон «лестницы» с формулами; пример с открытками.","advanced":"Олимпиадная задача из Карточки 2 и вопрос: при какой наценке налог 4% съедает больше половины прибыли?","photo":{"src":"lessons/img/10_27.jpg","author":"Kelly Sikkema","q":["Что вы видите на фото? Как это связано с нашей темой?","Почему государства делают налоги для малого бизнеса проще, чем для крупных компаний?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g10-l27.pptx","name":"27. После ярмарки — мой доход и налоги (10 кл).pptx","mb":1.4}},{"id":"10_28","g":10,"l":28,"topic":"Государственная поддержка МСП","module":"Финансовая грамотность","format":"Комбинированный","skills":["Финансовое мышление","Инициативность","Критическое мышление"],"goal":"К концу урока ученик сможет назвать 3 действующие формы государственной поддержки МСП в Казахстане и подобрать подходящую программу для заданной бизнес-идеи с обоснованием.","criteria":["Я называю 3 формы господдержки МСП и объясняю, чем они отличаются.","Я подбираю программу под бизнес-идею и обосновываю выбор.","Я называю, где проверить актуальные условия, и отличаю реальную поддержку от мошенничества."],"result":"Карточка «Бизнес-идея + поддержка»: описание идеи, подобранная программа (обучение, грант, льготный кредит или гарантия), обоснование и что проверить на официальном сайте.","stages":[{"stage":"Разминка «Найди пару»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"МСП","real":"Малое и среднее предпринимательство","shown":"Малое и среднее предпринимательство","truth":true,"first":"М"},{"term":"Государственная поддержка (help)","real":"Помощь государства бизнесу деньгами, гарантиями, обучением или консультациями","shown":"Небольшой кредит для начинающего предпринимателя","truth":false,"first":"Г"},{"term":"Грант","real":"Безвозвратные деньги на реализацию бизнес-идеи при выполнении условий","shown":"Безвозвратные деньги на реализацию бизнес-идеи при выполнении условий","truth":true,"first":"Г"},{"term":"Субсидирование ставки","real":"Государство оплачивает часть вознаграждения по кредиту предпринимателя","shown":"Помощь государства бизнесу деньгами, гарантиями, обучением или консультациями","truth":false,"first":"С"},{"term":"Гарантирование кредита","real":"Государство (через фонд) поручается за часть кредита, если у предпринимателя мало залога","shown":"Государство (через фонд) поручается за часть кредита, если у предпринимателя мало залога","truth":true,"first":"Г"},{"term":"Микрокредит","real":"Небольшой кредит для начинающего предпринимателя","shown":"Государство оплачивает часть вознаграждения по кредиту предпринимателя","truth":false,"first":"М"}],"perm":[3,2,1,0,5,4]},"glossary":[{"term":"МСП","def":"Малое и среднее предпринимательство"},{"term":"Государственная поддержка (help)","def":"Помощь государства бизнесу деньгами, гарантиями, обучением или консультациями"},{"term":"Грант","def":"Безвозвратные деньги на реализацию бизнес-идеи при выполнении условий"},{"term":"Субсидирование ставки","def":"Государство оплачивает часть вознаграждения по кредиту предпринимателя"},{"term":"Гарантирование кредита","def":"Государство (через фонд) поручается за часть кредита, если у предпринимателя мало залога"},{"term":"Микрокредит","def":"Небольшой кредит для начинающего предпринимателя"},{"term":"Бизнес-обучение","def":"Бесплатные курсы для начинающих предпринимателей"}],"english":"help — помощь; money — деньги","concepts":{"head":"Определения","items":["МСП — малый и средний бизнес.","Государственная поддержка (help) — помощь, которая снижает риск и стоимость денег (money) для предпринимателя: обучение, гранты, льготные кредиты, субсидирование ставки и гарантии."]},"steps":{"head":"Как это работает, по шагам","items":["Определить стадию бизнеса: идея, старт, рост","Подобрать форму: идея — обучение (проект «Бизнес Бастау» Национальной палаты предпринимателей «Атамекен»); старт — гранты на новые бизнес-идеи и микрокредиты; рост — субсидирование ставки и гарантирование кредитов через фонд «Даму»","Проверить условия на официальном сайте (damu.kz, atameken.kz, enbek.kz), так как программы и требования обновляются","Подготовить бизнес-план","Подать заявку. Важно: настоящая господдержка никогда не требует «предоплаты за оформление гранта»"]},"scheme":"«лестница бизнеса»: ступени «Идея → Старт → Рост», на каждой — подходящая поддержка: «обучение» → «грант, микрокредит» → «субсидирование, гарантия».","examples":[{"lab":"Казахстанский","text":"Молодой предприниматель из Кызылорды хочет открыть мастерскую по ремонту телефонов; сначала проходит «Бизнес Бастау», затем подаёт заявку на грант для новой бизнес-идеи."},{"lab":"Второй пример","text":"Условная кофейня в Павлодаре работает 3 года и хочет кредит 10 млн условных тенге на расширение; ей подходят субсидирование ставки и гарантия фонда «Даму»."}],"mistake":{"myth":"«Грант дают всем, кто попросит»","fix":"Нужны бизнес-план, соответствие условиям и отбор."},"check":[{"q":"Чем грант отличается от кредита?","a":"Грант не возвращают"},{"q":"Что даёт гарантия фонда?","a":"Помогает получить кредит при нехватке залога"},{"q":"Где проверить условия?","a":"На официальных сайтах"}],"kz":{"text":"Фонд развития предпринимательства «Даму» с 1997 года поддерживает малый и средний бизнес Казахстана: субсидирует ставки по кредитам и гарантирует кредиты, а НПП «Атамекен» проводит бесплатное обучение «Бизнес Бастау».","link":"это действующие инструменты поддержки."},"world":{"text":"Во многих странах есть агентства поддержки малого бизнеса: в США — Small Business Administration (SBA), созданная в 1953 году, предоставляет гарантии по кредитам и обучение. Это связано с ЦУР ООН 8.3 — поддержка малых и средних предприятий.","link":""},"fact":"Small Business Administration в США была создана в 1953 году, и за десятилетия при её поддержке получали кредиты компании, которые потом стали известными брендами. Это показывает, как господдержка помогает малому бизнесу вырасти.","cards":[{"n":"1","title":"Бизнес-идеи","lines":["А: Ученица колледжа из Шымкента хочет шить сумки на заказ, есть только идея и навыки.","Б: Семья из Костаная 2 года держит пекарню, нужна печь на условные 6 млн тенге, залога мало.","В: Выпускник из Актобе хочет открыть сервис доставки, есть бизнес-план и нужен стартовый капитал.","Задание: выберите одну идею, подберите форму поддержки (обучение, грант, микрокредит, субсидирование, гарантия), обоснуйте, укажите сайт для проверки."],"hand":"Сдать: карточку «Бизнес-идея + поддержка».","answers":[["Тренеру","А — обучение «Бизнес Бастау», затем грант; Б — кредит с гарантией и субсидированием «Даму»; В — грант на новую бизнес-идею или микрокредит."]]},{"n":"2","title":"Олимпиадная задача","lines":["Предприниматель берёт кредит 5 млн тенге на год под условные 20% годовых. Государство субсидирует половину ставки. Сколько вознаграждения заплатит предприниматель и сколько сэкономит?"],"hand":"Сдать: решение.","answers":[["","Без субсидии 1 млн; с субсидией 10% = 500 000; экономия 500 000 тенге."]]}],"homework":"Выбери одну программу поддержки на damu.kz, atameken.kz или enbek.kz и выпиши: для кого она, что даёт, 3 условия участия. Объясни, подходит ли она для твоей бизнес-идеи.","support":"Таблица «стадия бизнеса — форма поддержки»; список официальных сайтов; готовая бизнес-идея А.","advanced":"Олимпиадная задача из Карточки 2 и задание составить «объявление мошенника о гранте» с 3 скрытыми признаками для другой группы.","photo":{"src":"lessons/img/10_28.jpg","author":"Tim Mossholder","q":["Что вы видите на фото? Как это связано с нашей темой?","Почему государству выгодно помогать малому бизнесу?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g10-l28.pptx","name":"28. Государственная поддержка МСП (10 кл).pptx","mb":1.4}},{"id":"10_29","g":10,"l":29,"topic":"Финансовое мошенничество","module":"Финансовая грамотность","format":"Комбинированный","skills":["Финансовое мышление","Критическое мышление","Принятие решений"],"goal":"К концу урока ученик сможет распознать 5 признаков мошеннического финансового предложения и назвать порядок действий при подозрении на мошенничество.","criteria":["Я нахожу 5 признаков мошенничества в предложениях.","Я называю порядок действий при подозрении и при уже совершённом переводе.","Я объясняю, как защитить себя и близких, включая цифровую безопасность."],"result":"Алгоритм «Стоп — Проверь — Сообщи»: разобранные 4 предложения с отмеченными признаками и памятка действий при подозрении.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Мошенничество (fraud)","real":"Обман ради получения чужих денег или данных","shown":"Обман ради получения чужих денег или данных","truth":true,"first":"М"},{"term":"Финансы (finance)","real":"Деньги и всё, что с ними связано","shown":"Поддельные голос или видео, созданные ИИ","truth":false,"first":"Ф"},{"term":"Фишинг","real":"Поддельные сайты и сообщения, выманивающие пароли и данные карты","shown":"Поддельные сайты и сообщения, выманивающие пароли и данные карты","truth":true,"first":"Ф"},{"term":"Социальная инженерия","real":"Давление на эмоции (страх, жадность, срочность), чтобы человек сам отдал деньги","shown":"Деньги и всё, что с ними связано","truth":false,"first":"С"},{"term":"Финансовая пирамида","real":"Схема, где «доход» старым участникам платят из взносов новых","shown":"Схема, где «доход» старым участникам платят из взносов новых","truth":true,"first":"Ф"},{"term":"Дипфейк","real":"Поддельные голос или видео, созданные ИИ","shown":"Давление на эмоции (страх, жадность, срочность), чтобы человек сам отдал деньги","truth":false,"first":"Д"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Мошенничество (fraud)","def":"Обман ради получения чужих денег или данных"},{"term":"Финансы (finance)","def":"Деньги и всё, что с ними связано"},{"term":"Фишинг","def":"Поддельные сайты и сообщения, выманивающие пароли и данные карты"},{"term":"Социальная инженерия","def":"Давление на эмоции (страх, жадность, срочность), чтобы человек сам отдал деньги"},{"term":"Финансовая пирамида","def":"Схема, где «доход» старым участникам платят из взносов новых"},{"term":"Дипфейк","def":"Поддельные голос или видео, созданные ИИ"},{"term":"Лицензия","def":"Разрешение государства на финансовую деятельность"}],"english":"fraud — мошенничество; finance — финансы; money — деньги","concepts":{"head":"Определения","items":["Мошенничество (fraud) в финансах (finance) — обман с целью получить деньги (money) или данные.","Каналы: звонки, мессенджеры, фишинговые сайты, соцсети, дипфейки."]},"steps":{"head":"Как распознать и действовать, по шагам","items":["Пять признаков: 1 — гарантированный высокий доход без риска; 2 — срочность и давление; 3 — просьба кодов из SMS, CVV, паролей, удалённого доступа к телефону; 4 — вознаграждение за привлечение новых участников; 5 — нет лицензии на финансовые услуги (проверяется на сайте АРРФР)","Алгоритм при подозрении: «Стоп» — прервать разговор; «Проверь» — перезвонить в банк по номеру на карте, проверить компанию на сайте регулятора; «Сообщи» — рассказать близким, сообщить в банк","Если деньги уже переведены: срочно позвонить в банк и заблокировать карту, обратиться в полицию по номеру 102, сохранить скриншоты переписки"]},"scheme":"Светофор «Стоп — Проверь — Сообщи», рядом 5 иконок признаков и отдельный блок «Если уже перевёл: банк → 102 → скриншоты».","examples":[{"lab":"Казахстанский","text":"Жительнице Павлодара звонит «сотрудник банка» и голосом, похожим на голос её сына (дипфейк), просит срочно перевести 150 000 условных тенге. Признаки: срочность, давление, необычный канал."},{"lab":"Второй пример","text":"В соцсети «инвестиционная платформа» обещает 40% в месяц и бонус за друзей: признаки 1, 2, 4, 5."}],"mistake":{"myth":"«Со мной такого не случится, я умный»","fix":"Мошенники давят на эмоции, а не на знания."},"check":[{"q":"Может ли сотрудник банка попросить код из SMS?","a":"Нет"},{"q":"Как проверить лицензию?","a":"На сайте АРРФР"},{"q":"Что сделать первым, если перевёл деньги мошеннику?","a":"Позвонить в банк"}],"kz":{"text":"АРРФР и финансовый портал finreg.kz регулярно публикуют предупреждения о новых схемах мошенничества в Казахстане и список лицензированных организаций.","link":"проверка лицензии — один из 5 признаков."},"world":{"text":"Мошенничество с использованием ИИ, включая дипфейки голоса, — глобальная проблема; Интерпол и банки разных стран предупреждают о «звонках от родственников». Это связано с ЦУР ООН 16 «Мир, правосудие и эффективные институты».","link":""},"fact":"Термин «фишинг» (phishing) появился в середине 1990-х годов: так хакеры называли «ловлю» паролей пользователей сервиса America Online через поддельные сообщения. Написание через «ph» — отсылка к ранней хакерской субкультуре.","cards":[{"n":"1","title":"Четыре предложения","lines":["А: «Вы выиграли 500 000 тенге! Для получения оплатите комиссию 5 000 по ссылке».","Б: «Крипто-платформа: 40% в месяц гарантированно, бонус 10% за каждого друга, лицензия „в процессе“».","В: «Это служба безопасности банка. Для защиты счёта установите приложение удалённого доступа».","Г: «Банк сообщает о новом тарифе. Подробности — в официальном приложении банка» (без ссылок и просьб).","Задание: отметьте признаки 1–5 и решите: мошенничество или нет; для каждого — действие."],"hand":"Сдать: таблицу.","answers":[["Тренеру","А — 2, предоплата; Б — 1, 2, 4, 5; В — 2, 3; Г — признаков нет, проверить в приложении."]]},{"n":"2","title":"Уже перевёл","lines":["Ситуация: Самат перевёл 80 000 тенге «продавцу» на маркетплейсе вне платформы, товар не пришёл.","Задание: опишите 4 действия по порядку.","Олимпиадная задача: платформа обещает 40% в месяц с реинвестированием. Во сколько раз вырастет вклад за 12 месяцев?"],"hand":"Сдать: ответы и решение.","answers":[["","1,4¹² ≈ 56,7 раза — ни один честный бизнес не даёт такой доходности, это признак пирамиды."]]},{"n":"3","title":"Роли для сцены","lines":["«Мошенник»: звонит от «полиции», говорит, что счёт под угрозой, просит перевести деньги на «безопасный счёт».","«Ученик»: прерывает разговор, называет действия."],"hand":"Сдать: не нужно.","answers":[]}],"homework":"Вместе с одним взрослым из семьи договоритесь о «кодовом слове» для экстренных звонков и проверьте настройки безопасности банковского приложения (двухфакторная защита, лимиты). Запиши 3 вывода.","support":"Табличка 5 признаков с ключевыми словами; готовый алгоритм действий для заполнения.","advanced":"Олимпиадная задача из Карточки 2 и задание составить сценарий «дипфейк-звонка» и правильную реакцию на него.","photo":{"src":"lessons/img/10_29.jpg","author":"Hassan OUAJBIR","q":["Что вы видите на фото? Как это связано с нашей темой?","Как семье договориться о «кодовом слове» для защиты от таких звонков?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g10-l29.pptx","name":"29. Финансовое мошенничество (10 кл).pptx","mb":1.3}},{"id":"10_30","g":10,"l":30,"topic":"Итоговая работа за полугодие: все разделы","module":"Все разделы","format":"Итоговая работа","skills":["Финансовое мышление","Критическое мышление"],"goal":"К концу урока ученик сможет выполнить итоговую работу за полугодие: ответить на тест по всем разделам, включая финансовую грамотность, и решить практическое задание по бюджету, налогам и кредиту.","criteria":["Я правильно отвечаю на тестовые вопросы по разделам полугодия.","Я решаю практическое задание с полным ходом решения.","Я применяю стратегию работы со временем и проверяю работу по чек-листу."],"result":"Выполненная итоговая работа: тест из 12 вопросов, практическое задание «Финансовый месяц героя» и лист самопроверки.","stages":[{"stage":"Разминка «Угадай слово»","min":4},{"stage":"Выполнение работы","min":28},{"stage":"Самопроверка","min":4},{"stage":"Рефлексия","min":4}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Тестирование (testing)","real":"Проверка знаний с помощью заданий с выбором или кратким ответом","shown":"Проверка знаний с помощью заданий с выбором или кратким ответом","truth":true,"first":"Т"},{"term":"Стратегия (strategy)","real":"План действий для достижения цели, например порядок выполнения заданий","shown":"Реальная годовая стоимость кредита","truth":false,"first":"С"},{"term":"Повторение (review)","real":"Закрепление изученного перед проверкой","shown":"Закрепление изученного перед проверкой","truth":true,"first":"П"},{"term":"Бюджет","real":"План доходов и расходов","shown":"План действий для достижения цели, например порядок выполнения заданий","truth":false,"first":"Б"},{"term":"ИПЦ","real":"Индекс потребительских цен","shown":"Индекс потребительских цен","truth":true,"first":"И"},{"term":"ГЭСВ","real":"Реальная годовая стоимость кредита","shown":"План доходов и расходов","truth":false,"first":"Г"}],"perm":[1,0,5,4,3,2]},"glossary":[{"term":"Тестирование (testing)","def":"Проверка знаний с помощью заданий с выбором или кратким ответом"},{"term":"Стратегия (strategy)","def":"План действий для достижения цели, например порядок выполнения заданий"},{"term":"Повторение (review)","def":"Закрепление изученного перед проверкой"},{"term":"Бюджет","def":"План доходов и расходов"},{"term":"ИПЦ","def":"Индекс потребительских цен"},{"term":"ГЭСВ","def":"Реальная годовая стоимость кредита"},{"term":"НДС","def":"Налог на добавленную стоимость, 16%, входит в цену"}],"english":"testing — тестирование; strategy — стратегия; review — повторение","concepts":{"head":"Базовые понятия полугодия","items":["Бюджет: остаток = доходы − расходы.","Инфляция по ИПЦ: (корзина сейчас ÷ корзина в базовом периоде × 100) − 100.","Подушка = обязательные расходы × 3–6.","Кредит: переплата = все платежи + комиссии − сумма кредита; сравниваем по ГЭСВ.","Налоги: НДС в цене = цена × 16 ÷ 116; зарплата на руки = начислено − ОПВ 10% − ИПН 10% с (начислено − ОПВ − 129 750); ИП на упрощёнке — 4% от дохода.","КФГД: сберегательные вклады в тенге до 20 млн тенге.","Мошенничество: 5 признаков."]},"steps":{"head":"Стратегия работы, по шагам","items":["Просмотреть всю работу за 1 минуту","Сначала тест, сомнительные вопросы пометить","Практическое задание — данные, формула, расчёт, ответ с единицами","Вернуться к пометкам","Самопроверка"]},"scheme":"«часы работы»: 0–1 мин обзор, 1–12 тест, 12–26 практика, 26–28 возврат к пометкам; затем самопроверка.","examples":[{"lab":"Казахстанский","text":"Чек на 17 400 условных тенге содержит НДС 17 400 × 16 ÷ 116 = 2 400."},{"lab":"Второй пример","text":"Подушка при обязательных расходах 140 000 на 3 месяца — 420 000 тенге."}],"mistake":{"myth":"Застрять на одном трудном вопросе и не успеть практику","fix":"Пометить и вернуться."},"check":[{"q":"Почему НДС делят на 116?","a":"Цена уже включает налог"},{"q":"Что сравнивать в кредитах?","a":"Полную стоимость, ГЭСВ"},{"q":"С чего считается налог ИП на упрощёнке?","a":"С дохода"}],"kz":{"text":"Тенге, национальная валюта Казахстана, введён 15 ноября 1993 года, и все расчёты полугодия — бюджет, налоги, кредиты — велись в тенге по правилам 2026 года (НДС 16%, ИПН 10%, МРП 4 325 тенге). В начале урока тренер напоминает ключевые ставки, действующие в 2026 году.","link":"итоговая работа проверяет умение применять казахстанские правила."},"world":{"text":"Исследование PISA (ОЭСР) с 2012 года сравнивает финансовую грамотность 15-летних в разных странах на задачах о бюджете, кредитах и рисках. Это связано с ЦУР ООН 4 «Качественное образование». Вопрос после работы: какие задания этой работы, по-вашему, могли бы быть в международном тесте?","link":""},"fact":"Первые известные государственные экзамены для отбора чиновников проводились в Китае с эпохи Суй (около 605 года) и существовали более 1 300 лет, до 1905 года.","cards":[{"n":"1","title":"Тест (по 1 баллу)","lines":["1) Дефицит бюджета — это: а) доходы больше расходов; б) расходы больше доходов.","2) Если ИПЦ = 106, инфляция равна: а) 106%; б) 6%.","3) Подушка безопасности рассчитывается от: а) всех желаний; б) обязательных расходов.","4) ГЭСВ показывает: а) рекламную ставку; б) реальную стоимость кредита.","5) НДС в Казахстане в 2026 году: а) 16%; б) 4%.","6) НДС в цене 11 600 тенге: а) 1 856; б) 1 600.","7) ОПВ работника: а) 10%; б) 3,5%.","8) ОПВР платит: а) работник; б) работодатель.","9) Налог ИП на упрощёнке берётся с: а) прибыли; б) дохода.","10) Прямой налог: а) ИПН; б) НДС.","11) Работник 15 лет может работать не более: а) 24 часов в неделю; б) 40 часов.","12) Просьба назвать код из SMS — это: а) проверка банка; б) признак мошенничества."],"hand":"Сдать: бланк ответов.","answers":[["1","Б"],["2","Б"],["3","Б"],["4","Б"],["5","А"],["6","Б"],["7","А"],["8","Б"],["9","Б"],["10","А"],["11","А"],["12","Б"]]},{"n":"2","title":"Практика «Финансовый месяц героя» (12 баллов)","lines":["Герой: Динара, начислено 300 000 условных тенге.","1) Зарплата на руки.","2) Обязательные расходы 160 000. Подушка на 3 месяца?","3) Остаток бюджета при необязательных расходах 50 000?","4) Кредит 400 000: банк А — 12 × 37 000; банк Б — 12 × 36 000 + комиссия 15 000. Что выгоднее?","5) НДС в покупке на 6 960 тенге?"],"hand":"Сдать: решения с ходом расчёта.","answers":[["1","ОПВ 30 000; облагаемый 140 250; ИПН 14 025; на руки 255 975."],["2","480 000."],["3","45 975."],["4","А: переплата 44 000; Б: 47 000 — выгоднее А."],["5","960."]]},{"n":"3","title":"Чек-лист самопроверки","lines":["Ответил на все 12 вопросов.","В практике есть формулы.","Учёл вычет 129 750 в ИПН.","НДС считал через 116.","У ответов есть единицы."],"hand":"Сдать: вместе с работой.","answers":[]}],"homework":"Запиши 2 темы полугодия, в которых уверен, и 1 тему для разбора на следующем уроке с конкретным вопросом.","support":"Справочная строка с формулами (без ответов) в начале практики; увеличенный шрифт; дополнительные 3 минуты при необходимости.","advanced":"Дополнительное задание: оценить реальную доходность вклада под условные 11% при инфляции 7% за год (1,11 ÷ 1,07 ≈ 1,037, около 3,7%).","photo":{"src":"lessons/img/10_30.jpg","author":"Vitaly Gariev","q":["Что вы видите на фото? Как это связано с нашей темой?","Какие задания этой работы, по-вашему, могли бы быть в международном тесте?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g10-l30.pptx","name":"30. Итоговая работа за полугодие — все разделы (10 кл).pptx","mb":1.5}},{"id":"10_31","g":10,"l":31,"topic":"Работа над ошибками и обратная связь по итоговой работе","module":"Все разделы","format":"Итоговая работа","skills":["Критическое мышление"],"goal":"К концу урока ученик сможет проанализировать свои ошибки в итоговой работе, исправить их с объяснением правила и составить план устранения пробелов по обратной связи тренера.","criteria":["Я нахожу и классифицирую свои ошибки.","Я исправляю каждую ошибку и объясняю правило своими словами.","Я использую обратную связь тренера и составляю конкретный план."],"result":"Лист работы над ошибками: таблица «ошибка — тип — исправление — правило», решённые задачи на закрепление и личный план из 2 шагов.","stages":[{"stage":"Разминка «Найди пару»","min":4},{"stage":"Выполнение работы","min":28},{"stage":"Самопроверка","min":4},{"stage":"Рефлексия","min":4}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Ошибка (mistake)","real":"Неверный шаг или ответ, показывающий, что нужно доучить","shown":"Неверный шаг или ответ, показывающий, что нужно доучить","truth":true,"first":"О"},{"term":"Обратная связь (feedback)","real":"Конкретный комментарий о сильных сторонах и о том, что улучшить","shown":"Шаги, чтобы тема перестала вызывать ошибки","truth":false,"first":"О"},{"term":"Вычислительная ошибка","real":"Верный метод, неверная арифметика","shown":"Верный метод, неверная арифметика","truth":true,"first":"В"},{"term":"Понятийная ошибка","real":"Неверное понимание правила или термина","shown":"Конкретный комментарий о сильных сторонах и о том, что улучшить","truth":false,"first":"П"},{"term":"Ошибка чтения условия","real":"Пропущенное или неверно понятое слово в задании","shown":"Пропущенное или неверно понятое слово в задании","truth":true,"first":"О"},{"term":"План устранения пробелов","real":"Шаги, чтобы тема перестала вызывать ошибки","shown":"Неверное понимание правила или термина","truth":false,"first":"П"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Ошибка (mistake)","def":"Неверный шаг или ответ, показывающий, что нужно доучить"},{"term":"Обратная связь (feedback)","def":"Конкретный комментарий о сильных сторонах и о том, что улучшить"},{"term":"Вычислительная ошибка","def":"Верный метод, неверная арифметика"},{"term":"Понятийная ошибка","def":"Неверное понимание правила или термина"},{"term":"Ошибка чтения условия","def":"Пропущенное или неверно понятое слово в задании"},{"term":"План устранения пробелов","def":"Шаги, чтобы тема перестала вызывать ошибки"}],"english":"mistake — ошибка; feedback — обратная связь","concepts":{"head":"Определения","items":["Ошибка (mistake) — информация для роста.","Обратная связь (feedback) тренера показывает, что именно исправить.","Типы: вычислительные, понятийные, ошибки чтения условия."]},"steps":{"head":"Как работать, по шагам","items":["Отметить задания с потерянными баллами","Определить тип","Найти правило в конспекте","Решить заново с полным ходом","Записать правило своими словами","Решить похожую задачу","Спланировать 2 шага на неделю"]},"scheme":"Три корзины «Считаю», «Понимаю», «Читаю», куда ученики клеят стикеры с ошибками; самая полная корзина — тема общего повторения.","examples":[{"lab":"Казахстанский","text":"Ученик выделял НДС из чека 11 600 условных тенге как 16% от суммы и получил 1 856 вместо 1 600. Понятийная ошибка: цена уже содержит налог, правильно × 16 ÷ 116."},{"lab":"Второй пример","text":"В сравнении кредитов не учтена комиссия 15 000, и выбран не тот банк — ошибка чтения условия: правило «полная стоимость = платежи + комиссии»."}],"mistake":{"myth":"Переписать ответ с доски без объяснения","fix":"Правило должно быть сформулировано своими словами и проверено новой задачей."},"check":[{"q":"Чем понятийная ошибка опаснее вычислительной?","a":"Повторится в любой похожей задаче"},{"q":"Как не пропускать данные условия?","a":"Подчёркивать числа и слова «включая», «с учётом»"},{"q":"Как использовать обратную связь?","a":"Превратить её в конкретный шаг"}],"kz":{"text":"Казахстанские IT-компании, например резиденты технопарка Astana Hub, выпускают продукты итерациями: запускают версию, собирают отзывы, исправляют ошибки и выпускают новую.","link":"работа над ошибками — та же итерация, только для знаний."},"world":{"text":"В авиации действует международная культура разбора инцидентов: каждая ошибка анализируется, чтобы она не повторилась, и это сделало полёты очень безопасными.","link":""},"fact":"Компания 3M создала знаменитые стикеры Post-it благодаря «неудачному» клею, который изобрёл Спенсер Сильвер в 1968 году: клей держал слабо, и лишь позже коллега Арт Фрай нашёл ему применение.","cards":[{"n":"1","title":"Работа над ошибками","lines":["Таблица: № задания | Мой ответ | Тип (считаю / понимаю / читаю) | Правильное решение | Правило своими словами.","Внизу: «Мой план: 1) … 2) …»."],"hand":"Сдать: заполненную таблицу.","answers":[]},{"n":"2","title":"Задачи на закрепление","lines":["1) НДС в чеке 8 120 тенге. (1 120.)","2) Начислено 220 000. На руки?","3) Корзина: было 20 000, стало 21 400. Инфляция?","4) Кредит 300 000: 12 × 28 000 + комиссия 6 000. Переплата?","5) ИП: доход 150 000. Налог по упрощёнке?"],"hand":"Сдать: решения в тетради.","answers":[["2","ОПВ 22 000; облагаемый 68 250; ИПН 6 825; на руки 191 175."],["3","7%."],["4","42 000."],["5","6 000."]]}],"homework":"Выполни свой план: реши 2 задачи по теме с ошибкой и запиши правило своими словами.","support":"Образец заполненной строки таблицы; карточки-подсказки с правилами по каждой теме; консультант-одноклассник.","advanced":"Составить задачу «с ловушкой» по типичной ошибке класса с ответом и объяснением.","photo":{"src":"lessons/img/10_31.jpg","author":"lilartsy","q":["Что вы видите на фото? Как это связано с нашей темой?","Как подход «ошибка — источник знаний» можно применить в бизнесе и учёбе?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g10-l31.pptx","name":"31. Работа над ошибками и обратная связь по итоговой работе (10 кл).pptx","mb":1.3}},{"id":"10_32","g":10,"l":32,"topic":"Игра-повторение по темам полугодия","module":"Все разделы","format":"Деловая игра","skills":["Командная работа","Лидерство","Критическое мышление"],"goal":"К концу урока ученик сможет применить понятия полугодия (бюджет, инфляция, кредит, налоги, мошенничество) в командной игре и объяснить свои решения с опорой на расчёты.","criteria":["Я правильно решаю задачи и проверяю решения команды.","Я выполняю свою роль и участвую в общих решениях.","Я называю тему, которую закрепил, и что ещё повторить."],"result":"Командный «финансовый отчёт игры»: решения двух раундов, расчёты капитала и разбор ошибок.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":4},{"stage":"Инструктаж","min":4},{"stage":"Раунд 1","min":10},{"stage":"Раунд 2","min":10},{"stage":"Разбор","min":8},{"stage":"Рефлексия","min":4}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Повторение (review)","real":"Закрепление изученного через применение","shown":"Закрепление изученного через применение","truth":true,"first":"П"},{"term":"Игра (game)","real":"Учебная модель с правилами, ролями и результатом","shown":"Запас на 3–6 месяцев обязательных расходов","truth":false,"first":"И"},{"term":"Капитал","real":"Деньги команды для решений в игре","shown":"Деньги команды для решений в игре","truth":true,"first":"К"},{"term":"Полная стоимость кредита","real":"Сумма всех платежей и комиссий","shown":"Учебная модель с правилами, ролями и результатом","truth":false,"first":"П"},{"term":"НДС","real":"Налог 16%, входящий в цену","shown":"Налог 16%, входящий в цену","truth":true,"first":"Н"},{"term":"Подушка безопасности","real":"Запас на 3–6 месяцев обязательных расходов","shown":"Сумма всех платежей и комиссий","truth":false,"first":"П"}],"perm":[3,2,1,0,5,4]},"glossary":[{"term":"Повторение (review)","def":"Закрепление изученного через применение"},{"term":"Игра (game)","def":"Учебная модель с правилами, ролями и результатом"},{"term":"Капитал","def":"Деньги команды для решений в игре"},{"term":"Полная стоимость кредита","def":"Сумма всех платежей и комиссий"},{"term":"НДС","def":"Налог 16%, входящий в цену"},{"term":"Подушка безопасности","def":"Запас на 3–6 месяцев обязательных расходов"},{"term":"Узкое место","def":"Этап, тормозящий весь процесс"}],"english":"review — повторение; game — игра","concepts":{"head":"Определения","items":["Игра (game) «Семейный бизнес» — повторение (review) полугодия: каждая команда управляет условной семьёй с ИП и капиталом 500 000 тенге.","Цель — сохранить и увеличить капитал, принимая финансово грамотные решения."]},"steps":{"head":"Как играть, по шагам","items":["Роли — капитан, финансист, налоговый консультант, аналитик рисков","Раунд 1 — 5 расчётных задач (бюджет, НДС, зарплата, ИПЦ, кредит): верный ответ +20 000","Раунд 2 — события (кредитное предложение, налог ИП, мошенник, инфляция, поломка), решение и пересчёт капитала","Разбор"]},"scheme":"Табло команд «капитал — раунд 1 — раунд 2 — итог» и «карта тем»: бюджет, ИПЦ, подушка, банк, кредит, НДС, ИПН, ИП 4%, мошенничество.","examples":[{"lab":"Казахстанский","text":"Событие «ИП семьи получил доход 300 000 за месяц» — налог по упрощёнке 4% = 12 000; команда, забывшая налог, получает «штраф» 5 000."},{"lab":"Второй пример","text":"Событие «Два кредита на 200 000: А — 12 × 18 500; Б — 12 × 18 000 + комиссия 8 000». А: 222 000, Б: 224 000 — верный выбор А."}],"mistake":{"myth":"Решать быстро и игнорировать риск","fix":"Разбор на событии с мошенником."},"check":[{"q":"С чего берётся налог ИП на упрощёнке?","a":"С дохода"},{"q":"Как выбрать кредит?","a":"По полной стоимости"},{"q":"Что делать со «сверхвыгодным предложением»?","a":"Проверить 5 признаков"}],"kz":{"text":"Казахская национальная игра тоғызқұмалақ требует счёта и планирования на несколько ходов вперёд и включена в программы школьных соревнований.","link":"финансовая игра тоже требует считать последствия решений заранее."},"world":{"text":"Деловые игры и симуляции используют в бизнес-школах мира, например кейс-метод Гарвардской школы бизнеса, где студенты принимают решения за реальные компании.","link":""},"fact":"Гарвардская школа бизнеса начала активно использовать кейс-метод в 1920-х годах, и сегодня её кейсы применяются в бизнес-образовании по всему миру.","cards":[{"n":"1","title":"Правила «Семейного бизнеса»","lines":["Старт: 500 000 условных тенге. Роли: капитан, финансист, налоговый консультант, аналитик рисков.","Раунд 1: +20 000 за верный ответ.","Раунд 2: последствия решений. Бонус «помощь соседу» +10 000 один раз."],"hand":"Сдать: не нужно.","answers":[]},{"n":"2","title":"Раунд 1","lines":["1) Доходы 350 000, расходы 372 000. Остаток или дефицит?","2) НДС в цене 13 920. (1 920.)","3) Начислено 250 000. На руки?","4) Корзина 30 000 → 32 100. Инфляция?","5) Кредит 500 000: 24 × 25 000. Переплата?"],"hand":"Сдать: ответы.","answers":[["1","Дефицит 22 000."],["3","215 475."],["4","7%."],["5","100 000."]]},{"n":"3","title":"События раунда 2","lines":["1) «Доход ИП за месяц 300 000» — заплатить налог 4%?","2) «Два кредита на 200 000: А — 12 × 18 500; Б — 12 × 18 000 + комиссия 8 000». (Выбор А.)","3) «Звонок: „Служба безопасности, назовите код“». (Отказ 0; согласие −100 000.)","4) «Инфляция 8%: 100 000 свободных — наличные или вклад под условные 10%?» (Вклад +10 000; наличные −8 000 покупательной способности.)","5) «Поломка оборудования 80 000. Есть подушка?» (Есть — капитал −80 000; нет — кредит с переплатой 12 000.)"],"hand":"Сдать: решения на табло.","answers":[["1","12 000; не заплатил — минус 17 000."]]}],"homework":"Составь 3 вопроса викторины по темам, где ошибался в итоговой работе, с ответами и объяснениями.","support":"Памятка с формулами у каждой команды; помощник у финансиста.","advanced":"Роль «аналитика»: спрогнозировать влияние каждого события на капитал всех команд.","photo":{"src":"lessons/img/10_32.jpg","author":"National Cancer Institute","q":["Что вы видите на фото? Как это связано с нашей темой?","Чем решения в игре отличаются от реальных и чему игра всё же учит?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g10-l32.pptx","name":"32. Игра-повторение по темам полугодия (10 кл).pptx","mb":1.5}}];
